import {useRef} from 'react'

import useJobFilesPublicationStore from '../JobFilesPublication/useJobFilesPublicationStore'
import useJobOutputParametersStore from '../JobOutputParameters/useJobOutputParametersStore'

function useJobOutputs() {
  const {filesPublication} = useJobFilesPublicationStore()
  const {jobOutputParametersLength} = useJobOutputParametersStore()
  const isCollapsible = Boolean(filesPublication.length || jobOutputParametersLength)
  const addJobOutputsButtonRef = useRef<HTMLInputElement>(null)

  return {
    isCollapsible,
    addJobOutputsButtonRef,
  }
}

export default useJobOutputs
