import type {AnchorProps} from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {memo, useCallback} from 'react'

import useEventCallback from '../../../../../../../../../../hooks/useEventCallback'
import PopupMenu from '../../../../../../../../../common/Popup/PopupMenu.lazy'
import {directions} from '../SelfHostedRequirements.consts'
import type {OSFamilyRequirement, OSVersionRequirement} from '../SelfHostedRequirements.types'

import OSFilter from './Filter/OSFilter'
import {useOSRequirement} from './OSRequirement.hooks'

interface Props {
  osFamilyRequirement: OSFamilyRequirement
  osVersionRequirement?: OSVersionRequirement
  onAdd: (nextRequirement: OSFamilyRequirement | OSVersionRequirement) => void
  onChange: (
    prevRequirement: OSFamilyRequirement | OSVersionRequirement,
    nextRequirement: OSFamilyRequirement | OSVersionRequirement,
  ) => void
  onRemove: (requirement: OSFamilyRequirement | OSVersionRequirement) => void
}

function OSRequirementComponent(props: Props) {
  const {osFamilyRequirement, osVersionRequirement, onAdd, onChange, onRemove} = props
  const {data, currentOsFamilyRequirement, currentOsVersionRequirement, reset} = useOSRequirement({
    osFamilyRequirement,
    osVersionRequirement,
  })

  const handleRemoveClick = useEventCallback(() => {
    onRemove(osFamilyRequirement)

    if (osVersionRequirement) {
      onRemove(osVersionRequirement)
    }
  })

  const anchor = useCallback(
    ({active}: AnchorProps) => (
      <OSFilter
        active={active}
        osFamilyRequirement={currentOsFamilyRequirement}
        osVersionRequirement={currentOsVersionRequirement}
        onRemoveClick={handleRemoveClick}
      />
    ),
    [currentOsFamilyRequirement, currentOsVersionRequirement, handleRemoveClick],
  )

  const onHide = useEventCallback(() => {
    if (currentOsFamilyRequirement) {
      onChange(osFamilyRequirement, currentOsFamilyRequirement)
    }
    if (osVersionRequirement == null) {
      onAdd(currentOsVersionRequirement)
    } else {
      onChange(osVersionRequirement, currentOsVersionRequirement)
    }
    reset()
  })

  return (
    <Dropdown data-test={'os-requirement'} anchor={anchor} clickMode onHide={onHide}>
      <PopupMenu offset={4} directions={directions} data={data} minWidth={210} />
    </Dropdown>
  )
}

export default memo(OSRequirementComponent)
