import type {IconType} from '@jetbrains/ring-ui-built/components/icon/icon'

import {SelfHostedRequirementType} from '../SelfHostedRequirements.types'

import ArchIcon from 'src/svg/cpu-chip-arch.svg'
import CountIcon from 'src/svg/cpu-chip-count.svg'
import RamIcon from 'src/svg/keyboard.svg'
import MonitorIcon from 'src/svg/monitor.svg'

export enum SelfRequirementsPopupMode {
  MAIN = 'Main',
  OS = 'OS',
  CPU_COUNT = 'CPU count',
  CPU_ARCH = 'CPU arch',
  RAM_AMOUNT = 'RAM amount',
}

export function toPopupMode(mode: SelfHostedRequirementType): SelfRequirementsPopupMode {
  switch (mode) {
    case SelfHostedRequirementType.OS:
      return SelfRequirementsPopupMode.OS
    case SelfHostedRequirementType.CPU_COUNT:
      return SelfRequirementsPopupMode.CPU_COUNT
    case SelfHostedRequirementType.CPU_ARCH:
      return SelfRequirementsPopupMode.CPU_ARCH
    case SelfHostedRequirementType.RAM_AMOUNT:
      return SelfRequirementsPopupMode.RAM_AMOUNT
    default:
      return SelfRequirementsPopupMode.MAIN
  }
}

export function getPopupModeIcon(mode: SelfHostedRequirementType): IconType | null {
  switch (mode) {
    case SelfHostedRequirementType.OS:
      return MonitorIcon
    case SelfHostedRequirementType.CPU_COUNT:
      return CountIcon
    case SelfHostedRequirementType.CPU_ARCH:
      return ArchIcon
    case SelfHostedRequirementType.RAM_AMOUNT:
      return RamIcon
    default:
      return null
  }
}
