import {memo} from 'react'

import {dependencyCacheEnabled} from '../../../../../utils/featureToggles'
import useJobAllowReuse from '../../JobAllowReuse/JobAllowReuse.hooks'
import useJobEnableDependencyCache from '../../JobEnableDependencyCache/JobEnableDependencyCache.hooks'
import useJobParallelism from '../../JobParallelism/JobParallelism.hooks'

type Props = {
  jobId: string
}
function JobOptimizationsNote({jobId}: Props) {
  const {parallelismCount} = useJobParallelism(jobId)
  const {isDependencyCacheEnabled} = useJobEnableDependencyCache(jobId)
  const {jobAllowReuse} = useJobAllowReuse(jobId)

  return (
    <>
      <div>{!!parallelismCount && 'Parallel Tests'}</div>
      <div>{dependencyCacheEnabled && isDependencyCacheEnabled && 'Dependency Cache'}</div>
      <div>{jobAllowReuse && 'Reuse Job Results'}</div>
    </>
  )
}

export default memo(JobOptimizationsNote)
