import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import {Markdown, LinkOpenPolicy} from '@jetbrains/teamcity-ui/dist/components'
import {memo} from 'react'

import {DESCRIPTION, LABEL} from './JobEnableDependencyCache.consts'
import useJobEnableDependencyCache from './JobEnableDependencyCache.hooks'
import type {JobEnableDependencyCacheProps} from './JobEnableDependencyCache.types'

import styles from './JobEnableDependencyCache.module.css'

import HelpDetails from 'src/components/common/HelpDetails/HelpDetails'

function JobEnableDependencyCache({jobId}: JobEnableDependencyCacheProps) {
  const {handlerEnableDependencyCacheToggle, isDependencyCacheEnabled, isApplicable} =
    useJobEnableDependencyCache(jobId)

  return (
    <div className={styles.container}>
      <Toggle
        onChange={handlerEnableDependencyCacheToggle}
        checked={isDependencyCacheEnabled}
        disabled={!isApplicable}
      >
        {LABEL}
      </Toggle>
      {DESCRIPTION && (
        <HelpDetails>
          <Markdown className={styles.description} linkOpenPolicy={LinkOpenPolicy.ALL_IN_NEW_TAB}>
            {DESCRIPTION.trim()}
          </Markdown>
        </HelpDetails>
      )}
    </div>
  )
}

export default memo(JobEnableDependencyCache)
