import {memo} from 'react'

import FilterRequirement from '../../Filter/FilterRequirement'
import mainStyles from '../../SelfHostedRequirements.module.css'

import RamIcon from 'src/svg/keyboard.svg'

interface Props {
  value?: string
  onRemoveClick?: () => void
  active: boolean
}

function RAMFilter(props: Props) {
  const {value, onRemoveClick, active} = props
  return (
    <FilterRequirement
      data-test={'ram-filter-requirement'}
      icon={RamIcon}
      active={active}
      onRemoveClick={onRemoveClick}
    >
      {`RAM amount is `}
      {value && <span className={mainStyles.bold}>{value}</span>}
    </FilterRequirement>
  )
}

export default memo(RAMFilter)
