import {useSearchParams} from 'react-router'

import {useAppDispatch, useAppSelector} from '../../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {pipelineDraft, pipelineErrors} from '../../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../../slices/EditPipelinePage.slices.types'
import {sideBarNavigatiobSearchParam} from '../../../SettingsSidebarContent.const'

import useJobStepGenerateDefaultSummarize from './useJobStepGenerateDefaultSummarize'

function useJobStepRunnerSummarizePreview(
  jobId: string,
  originalIndex: number,
  cloneStepHandler: (index: number) => void,
  selectedType: string,
) {
  const {summarizeText, isSummarizeTextLoading} = useJobStepGenerateDefaultSummarize(
    jobId,
    originalIndex,
  )
  const pipelineId = usePipelineId()
  const dispatch = useAppDispatch()
  const [searchParams, setSearchParams] = useSearchParams()
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const deleteStepButtonClickHandler = () => {
    dispatch(pipelineDraft.actions.deleteStep({id: pipelineId, jobId, index: originalIndex}))
    dispatch(
      pipelineErrors.actions.clear({
        pipelineId,
        jobId,
        formType: FormType.STEP,
        formId: originalIndex,
      }),
    )
  }
  const isDeleted = useAppSelector(state =>
    state.pipelines.pipelineDraft[pipelineId]?.deleted?.steps?.[jobId]?.includes(originalIndex),
  )
  const clickCloneRunnerHandler = () => cloneStepHandler(originalIndex)
  const clickRestoreButtonHandler = () =>
    dispatch(pipelineDraft.actions.restoreStep({id: pipelineId, jobId, index: originalIndex}))
  const clickEditButtonHandler = () =>
    setSearchParams({
      ...searchParamsObject,
      [sideBarNavigatiobSearchParam.step]: originalIndex.toString(),
    })

  return {
    isDeleted,
    selectedType,
    summarizeDetailsText: summarizeText,
    isSummarizeDetailsTextLoading: isSummarizeTextLoading,
    clickRestoreButtonHandler,
    clickCloneRunnerHandler,
    deleteStepButtonClickHandler,
    clickEditButtonHandler,
  }
}

export default useJobStepRunnerSummarizePreview
