import {Fragment} from 'react'

import Icon from '../../../../../../../../common/Icon/Icon'
import RouterLink from '../../../../../../../../common/RouterLink/RouterLink'
import {FullLogTarget} from '../../../../../../../../packages/BuildLog/BuildLog.types'
import {getFullBuildLogLinkParams} from '../../../../../../../../packages/BuildLog/BuildLog.utils'

import styles from './JobStepRunnerSummarizeErrorPreview.module.css'

type JobStepRunnerSummarizeErrorPreviewProps = {
  stepErrorMessage?: string
  failureId?: number | null
  buildAnchor?: number | null
  pointType?: string
}

function JobStepRunnerSummarizeErrorPreview({
  stepErrorMessage,
  failureId,
  buildAnchor,
  pointType,
}: JobStepRunnerSummarizeErrorPreviewProps) {
  return (
    <Fragment>
      {stepErrorMessage}
      {buildAnchor != null && failureId != null ? (
        <div className={styles.failureLine}>
          <RouterLink
            params={getFullBuildLogLinkParams({
              buildId: failureId,
              line: buildAnchor,
              expandState: [buildAnchor],
              target: FullLogTarget.POPUP,
              expandAll: false,
            })}
            className={styles.failure}
          >
            <Icon name="finished_red" className={styles.icon} />
            {pointType === 'FAILURE' ? 'Failed' : 'Unknown event'}
          </RouterLink>
          <RouterLink
            className={styles.logLink}
            params={getFullBuildLogLinkParams({
              buildId: failureId,
              line: buildAnchor,
              expandState: [buildAnchor],
              target: FullLogTarget.POPUP,
              expandAll: false,
            })}
          >
            {'Show build log'}
          </RouterLink>
        </div>
      ) : null}
    </Fragment>
  )
}

export default JobStepRunnerSummarizeErrorPreview
