import {useMemo} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {emptyArray, emptyObject} from '../../../../../../../utils/empty'
import {usePipelineId} from '../../../../hooks/pipeline'
import type {VcsRootDto} from '../../../../services/pipelinesApi.types'
import type {JobRepositorySettings} from '../../../../types'
import {useJobId, usePipelineAdditionalVcsRootsOrDraft} from '../../../EditPipelinePage.hooks'
import {getDraft, getDraftJobs} from '../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../slices/EditPipelinePage.slices'
import {useDeletedRepositoriesSet} from '../../PipelineSettingsSidebar/PipelineRepositories/PipelineRepositories.hooks'

import {mainRepositoryName} from './JobRepositories.consts'
import {getRepositoryShortNotice} from './JobRepositories.utils'

function useJobRepositories() {
  const dispatch = useAppDispatch()
  const jobId = useJobId()!
  const pipelineId = usePipelineId()
  const deletedRepositoriesSet = useDeletedRepositoriesSet()
  const mainVcsRoot =
    useAppSelector(state => getDraft(state, pipelineId)?.vcsRoot) ?? (emptyObject as VcsRootDto)
  const mainRepositoryId = mainVcsRoot?.id
  const additionalVcsRoots = usePipelineAdditionalVcsRootsOrDraft()
  const pipelineVcsRoots = useMemo(
    () => [mainVcsRoot, ...additionalVcsRoots],
    [additionalVcsRoots, mainVcsRoot],
  )
  const jobRepositories =
    useAppSelector(state => getDraftJobs(state, pipelineId)?.[jobId]?.repositories) ??
    (emptyArray as Record<string, JobRepositorySettings>[])
  const jobRepositoriesMap = useMemo(
    () =>
      new Map(
        jobRepositories
          .map<[string, JobRepositorySettings]>(jobRepository => {
            const [url] = Object.keys(jobRepository)
            return [url, jobRepository[url]]
          })
          .filter(([url]) => !deletedRepositoriesSet.has(url)),
      ),
    [deletedRepositoriesSet, jobRepositories],
  )
  const isMainRepositoryDisabled = jobRepositoriesMap.get(mainRepositoryName)?.enabled === false
  const isMainRepositoryNone = jobRepositoriesMap.get(mainRepositoryName) == null
  const shortNoticeRepositories = useMemo(
    () =>
      pipelineVcsRoots
        .reduce<string[]>((accumulator, {id, name, url, isExternal}) => {
          const isMainRepository = mainRepositoryId === id
          const repositoryUrl = isMainRepository ? mainRepositoryName : url
          const repository = jobRepositoriesMap.get(repositoryUrl)
          const isAdded = isMainRepository && repository == null ? true : !!repository?.enabled

          if (isAdded) {
            const shortNotice = getRepositoryShortNotice({name, url, isExternal})
            if (shortNotice != null) {
              accumulator.push(shortNotice)
            }
          }

          return accumulator
        }, [])
        .join('; '),
    [jobRepositoriesMap, mainRepositoryId, pipelineVcsRoots],
  )
  const jobRepositoryChangePath = (url: string) => (value: {enabled: boolean; path?: string}) =>
    dispatch(
      pipelineDraft.actions.updateJobRepository({
        url,
        pipelineId,
        jobId,
        settings: value,
      }),
    )
  const settingsBlockTitle = useMemo(() => {
    const hasMainRepository = jobRepositoriesMap.get(mainRepositoryName)?.enabled !== false
    const jobRepositoriesLength = jobRepositoriesMap.size
    const hasRepositories = hasMainRepository || (!hasMainRepository && jobRepositoriesLength > 1)

    return hasRepositories ? 'Repository' : 'No Active Repositories'
  }, [jobRepositoriesMap])

  return {
    settingsBlockTitle,
    deletedRepositoriesSet,
    shortNoticeRepositories,
    pipelineVcsRoots,
    mainRepositoryId,
    jobRepositoriesMap,
    isMainRepositoryDisabled,
    isMainRepositoryNone,
    jobRepositoryChangePath,
  }
}

export default useJobRepositories
