import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import {Suspense, useEffect, useRef} from 'react'
import type {EntryPointProps} from 'react-relay'
import {useNavigate} from 'react-router'

import {useAppSelector} from '../../../../../../hooks/react-redux'
import {DisabledContext} from '../../../contexts/DisabledContext'
import type {pipelineHeadBuildTypeFragment$key} from '../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineId} from '../../../hooks/pipeline'
import {useIsJobDeleted, useJobId, usePipelineJobIdsOrDraft} from '../../EditPipelinePage.hooks'
import {getDraft} from '../../EditPipelinePage.selectors'

import type {JobAgentRequirementsCloudImagesQuery} from './JobAgentRequirements/__generated__/JobAgentRequirementsCloudImagesQuery.graphql'
import JobAgentRequirements from './JobAgentRequirements/JobAgentRequirements'
import JobDependencies from './JobDependencies/JobDependencies'
import JobIntegrations from './JobIntegrations/JobIntegrations'
import JobName from './JobName/JobName'
import JobOptimizations from './JobOptimizations/JobOptimizations'
import JobOutputs from './JobOutputs/JobOutputs'
import JobParameters from './JobParameters/JobParameters'
import JobRepositories from './JobRepositories/JobRepositories'
import JobSettingsFooter from './JobSettingsFooter/JobSettingsFooter'
import JobSettingsOverlay from './JobSettingsOverlay/JobSettingsOverlay'
import JobSteps from './JobSteps/JobSteps'

import styles from './JobSettingsSidebar.module.css'

type Props = {pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null}
type Queries = {cloudImages: JobAgentRequirementsCloudImagesQuery}
export default function JobSettingsSidebar({
  queries,
  props,
}: EntryPointProps<Queries, {}, Props, {}>) {
  const {pipelineHeadBuildTypeKey} = props
  const id = useJobId()!
  const jobIds = usePipelineJobIdsOrDraft()
  const pipelineId = usePipelineId()
  const isLoaded = useAppSelector(state => getDraft(state, pipelineId) != null)
  const navigate = useNavigate()
  const isNotFound = isLoaded && !jobIds.includes(id)
  const isMounted = useRef(false)
  const isDeleted = useIsJobDeleted(id)

  useEffect(() => {
    if (isNotFound && !isMounted.current) {
      navigate({search: objectToQuery({edit: 'true'})}, {replace: true, preventScrollReset: true})
    }
    isMounted.current = true
  }, [isNotFound, navigate])

  return (
    <DisabledContext.Provider value={isDeleted}>
      <div className={styles.container}>
        <JobName jobId={id} />
        <JobDependencies jobId={id} />
        <JobSteps jobId={id} pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey} />
        <JobOptimizations jobId={id} pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey} />
        <Suspense>
          <JobAgentRequirements jobId={id} cloudImagesQueryRef={queries.cloudImages} />
        </Suspense>
        <JobParameters />
        <JobOutputs />
        <JobRepositories />
        <JobIntegrations />
        <JobSettingsOverlay jobId={id} />
        <Suspense>
          <JobSettingsFooter jobId={id} />
        </Suspense>
      </div>
    </DisabledContext.Provider>
  )
}
export type JobSettingsSidebarComponent = typeof JobSettingsSidebar
