import {memo} from 'react'

import FilterRequirement from '../../Filter/FilterRequirement'
import styles from '../../SelfHostedRequirements.module.css'

import CountIcon from 'src/svg/cpu-chip-count.svg'

interface Props {
  value?: number
  onRemoveClick?: () => void
  active: boolean
}

function CPUFilter(props: Props) {
  const {value, onRemoveClick, active} = props
  return (
    <FilterRequirement
      data-test={'cpu-filter-requirement'}
      active={active}
      onRemoveClick={onRemoveClick}
      icon={CountIcon}
    >
      {`CPU count at least `}
      {value && <span className={styles.bold}>{value}</span>}
    </FilterRequirement>
  )
}

export default memo(CPUFilter)
