import deepEqual from 'fast-deep-equal'
import type * as React from 'react'
import {memo} from 'react'

import {emptyArray} from '../../../../../../../utils/empty'
import SettingsBlock from '../../../../components/SettingsBlock/SettingsBlock'
import {usePipelineId} from '../../../../hooks/pipeline'
import {useDoesJobExist} from '../../../EditPipelinePage.hooks'
import {getDraftJobs, getOriginalPipelineSettings} from '../../../EditPipelinePage.selectors'
import {getDependencyName} from '../../../EditPipelinePage.utils'

import {useDependencies, useToggleDependency} from './JobDependencies.hooks'
import JobDependenciesNote from './JobDependenciesNote/JobDependenciesNote'
import JobDependency from './JobDependency/JobDependency'

import styles from './JobDependencies.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  jobId: string
}

function JobDependencies({jobId}: Props) {
  const pipelineId = usePipelineId()
  const filesDependencies = useAppSelector(
    state => getDraftJobs(state, pipelineId)?.[jobId]?.dependencies,
  )
  const isExisting = useDoesJobExist(jobId)
  const savedDependencies =
    useAppSelector(getOriginalPipelineSettings(pipelineId))?.jobs?.[jobId]?.dependencies ??
    emptyArray
  const {dependencies, possibleDependencies} = useDependencies(jobId)
  const toggleDependency = useToggleDependency()

  const handleDependencyCheckboxChange =
    (dependencyId: string) =>
    ({currentTarget}: React.ChangeEvent<HTMLInputElement>) =>
      toggleDependency(jobId, dependencyId, currentTarget.checked)

  if (!possibleDependencies.length) {
    return null
  }

  return (
    <SettingsBlock
      id="dependencies"
      collapsible
      collapsedDefault={false}
      collapsedNote={<JobDependenciesNote dependencies={Array.from(dependencies)} />}
      title="Dependencies"
    >
      <div className={styles.dependencies}>
        {possibleDependencies.map((depId, index) => {
          const enabled = dependencies.has(depId)
          const wasEnabled = savedDependencies.some(dep => getDependencyName(dep) === depId)
          const files = filesDependencies?.[index]
          const sevedFiles = savedDependencies[index]
          const isFilesEqual = deepEqual(sevedFiles, files)
          const isUnsaved = (isExisting && enabled !== wasEnabled) || !isFilesEqual

          return (
            <JobDependency
              onEnabled={handleDependencyCheckboxChange(depId)}
              jobId={jobId}
              key={depId}
              depId={depId}
              enabled={enabled}
              unsaved={isUnsaved}
            />
          )
        })}
      </div>
    </SettingsBlock>
  )
}

export default memo(JobDependencies)
