import IconArtifacts from '@jetbrains/icons/artifacts-12px.svg'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import classNames from 'classnames'
import {memo} from 'react'

import Actions from '../../../../components/Actions/Actions'
import EditButton from '../../../../components/EditButton/EditButton'
import HighlighterTextView from '../../../../components/HighlighterTextField/HighlighterTextView'
import SummaryDetailsCardWrapper from '../../../../components/SummaryDetailsCardWrapper/SummaryDetailsCardWrapper'

import JobFilesPublicationSummaryDetailsHeader from './JobFilesPublicationSummaryDetailsHeader'
import useJobFilesPublication from './useJobFilesPublication'

import styles from './JobFilesPublication.module.css'

function JobFilesPublication() {
  const {
    listItemLimit,
    isBlockExpanded,
    getIsKeyDelete,
    isShowMoreButton,
    filesPublication,
    filesPublicationLength,
    clickShowMoreButtonHandler,
    clickEditJobSharedFilesHandler,
    clickRestoreFilePublicationButtonClickHandler,
    clickDeleteFilePublicationButtonClickHandler,
  } = useJobFilesPublication()

  if (!filesPublicationLength) {
    return null
  }

  return (
    <SummaryDetailsCardWrapper
      actions={
        <EditButton title="Edit" aria-label="Edit" onClick={clickEditJobSharedFilesHandler} />
      }
      header={<JobFilesPublicationSummaryDetailsHeader />}
      expanded={isBlockExpanded}
      showMoreButton={isShowMoreButton}
      onClickShowMore={clickShowMoreButtonHandler}
    >
      <div className={styles.content}>
        {filesPublication.slice(0, listItemLimit).map((file, index) => {
          const key = `key_${index}`
          const isFileDeleted = getIsKeyDelete(index)
          const className = classNames(styles.file, {
            [styles.fileDeleted]: isFileDeleted,
          })

          return (
            <div className={className} key={key}>
              {file['publish-artifact'] && (
                <Tooltip title={'File is published as Artifact'}>
                  <IconArtifacts className={styles.artifactsIcon} />
                </Tooltip>
              )}
              <HighlighterTextView value={file} />
              <Actions
                className={styles.parameterActions}
                deleted={isFileDeleted}
                onRestoreClick={clickRestoreFilePublicationButtonClickHandler(index)}
                onDeleteClick={clickDeleteFilePublicationButtonClickHandler(index)}
              />
            </div>
          )
        })}
      </div>
    </SummaryDetailsCardWrapper>
  )
}

export default memo(JobFilesPublication)
