import {useIsJobDeleted} from '../../../EditPipelinePage.hooks'

import styles from './JobSettingsOverlay.module.css'

type Props = {
  jobId: string
}

function JobSettingsOverlay({jobId}: Props) {
  const isDeleted = useIsJobDeleted(jobId)

  return isDeleted ? <div className={styles.overlay} /> : null
}

export default JobSettingsOverlay
