import {useEffect, useRef} from 'react'
import type * as React from 'react'

function useJobRepositoryForm(onChange: (value?: string) => void) {
  const inputFolderRef = useRef<HTMLInputElement>(null)
  const changeInputPathHandler = ({currentTarget}: React.ChangeEvent<HTMLInputElement>) =>
    onChange(currentTarget.value)

  useEffect(() => {
    requestAnimationFrame(() => inputFolderRef.current?.focus())
  }, [])

  return {
    inputFolderRef,
    changeInputPathHandler,
  }
}

export default useJobRepositoryForm
