import {memo, useCallback} from 'react'
import {useSearchParams} from 'react-router'

import {usePipelineId} from '../../../../hooks/pipeline'
import usePipelineDocumentTitle from '../../../../hooks/usePipelineDocumentTitle'
import {
  useGenerateFreeJobId,
  useHasNonDeletedDependants,
  usePipelineExistingJobIdsSet,
} from '../../../EditPipelinePage.hooks'
import {getJobName} from '../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../slices/EditPipelinePage.slices'
import NameSection from '../../NameSection/NameSection'
import JobId from '../JobId/JobId'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type Props = {
  jobId: string
}

function JobName({jobId}: Props) {
  const pipelineId = usePipelineId()
  const name = useAppSelector(state => getJobName(state, pipelineId, jobId))
  const dispatch = useAppDispatch()

  usePipelineDocumentTitle(`Edit ${name}`)

  const existingJobIds = usePipelineExistingJobIdsSet()
  const isNew = !existingJobIds.has(jobId)
  const generateFreeJobId = useGenerateFreeJobId()
  const [searchParams, setSearchParams] = useSearchParams()

  const hasNonDeletedDependants = useHasNonDeletedDependants(jobId)

  const onNameChange = useCallback(
    (newName: string) =>
      dispatch(
        pipelineDraft.actions.setJobName({
          pipelineId,
          value: newName,
          jobId,
        }),
      ),
    [dispatch, jobId, pipelineId],
  )

  const onConfirm = async () => {
    if (isNew && !hasNonDeletedDependants) {
      const newId = await generateFreeJobId(name)

      dispatch(
        pipelineDraft.actions.changeJobId({
          pipelineId,
          jobId,
          newId,
        }),
      )
      setSearchParams({...Object.fromEntries(searchParams), job: newId})
    }
  }

  return (
    <NameSection
      key={jobId}
      name={name}
      aria-label={'Job Name'}
      onNameChange={onNameChange}
      onConfirm={onConfirm}
      isJob
    >
      <JobId jobId={jobId} />
    </NameSection>
  )
}

export default memo(JobName)
