import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'

import {bannerIcons} from '../../PipelineRunPage/PipelineTab/Banners/Banner/Banner.types'
import {AlertMessageType} from '../../types/AlertMessages'

import type {AlertInfoMessageProps} from './AlertInfoMessage.types'
import {AlertInfoMessageVarian} from './AlertInfoMessage.types'

import styles from './AlertInfoMessage.module.css'

function AlertInfoMessage({
  children,
  className,
  type = AlertMessageType.INFO,
  variant = AlertInfoMessageVarian.STANDARD,
  ...props
}: AlertInfoMessageProps) {
  const isShowIcon = variant === AlertInfoMessageVarian.FILLED
  const containerClassNames = classNames(styles.container, styles[type], styles[variant], className)

  return (
    <div className={containerClassNames} {...props}>
      {isShowIcon && <SvgIcon className={styles.icon} icon={bannerIcons[type]} />}
      {children}
    </div>
  )
}

export default AlertInfoMessage
