import PipelineParametersSettingsBlockSummaryDetails from '../../../../components/PipelineParametersSettingsBlock/PipelineParametersSettingsBlockSummaryDetails'
import usePipelineParametersSettingsBlock from '../../../../components/PipelineParametersSettingsBlock/usePipelineParametersSettingsBlock'
import ParametersControlProvider from '../../../../contexts/ParametersControl/ParametersControlContext'

import JobOutputParametersSummaryDetailsHeader from './JobOutputParametersSummaryDetailsHeader'
import useJobOutputParameters from './useJobOutputParameters'

function JobOutputParameters() {
  const {
    jobOutputParameters,
    jobOutputParametersKeys,
    jobOutputParametersLength,
    deletedJobOutputParameters,
    parametersControlValue,
    jobOutputParametersFormErrorMessage,
    clickEditJobParametersHandler,
  } = useJobOutputParameters()
  const {listItemLimit, isShowMoreButton, isBlockExpanded, clickShowMoreButtonHandler} =
    usePipelineParametersSettingsBlock(jobOutputParameters)

  if (!jobOutputParametersLength) {
    return null
  }

  return (
    <ParametersControlProvider value={parametersControlValue}>
      <PipelineParametersSettingsBlockSummaryDetails
        header={<JobOutputParametersSummaryDetailsHeader />}
        parametersKeys={jobOutputParametersKeys}
        isBlockExpanded={isBlockExpanded}
        isShowMoreButton={isShowMoreButton}
        onClickShowMore={clickShowMoreButtonHandler}
        error={jobOutputParametersFormErrorMessage}
        onEdit={clickEditJobParametersHandler}
        parameters={jobOutputParameters}
        deleted={deletedJobOutputParameters}
        listItemLimit={listItemLimit}
      />
    </ParametersControlProvider>
  )
}

export default JobOutputParameters
