import throttle from 'lodash/throttle'
import {createContext, useContext, useEffect, useMemo} from 'react'

import {useRefetchableLazyLoadQuery} from '../../../../../../../../hooks/relay/useRefetchableLazyLoadQuery'
import {subscribeOnOverallEvents} from '../../../../../../../../utils/subscriber'
import {REGULAR_OVERALL_AGENT_EVENT_TOPICS} from '../../../../../../AgentsPages/AgentsPages.actions'

import type {
  SelfHostedRequirementsQuery$data,
  SelfHostedRequirementsQuery,
} from './Requirements/__generated__/SelfHostedRequirementsQuery.graphql'
import {selfHostedRequirementsQuery} from './Requirements/SelfHostedRequirements.queries'

interface JobAgentSelfHostedContextValue {
  agents: NonNullable<SelfHostedRequirementsQuery$data['agentsRest']>['agent']
  osFamilies: Record<string, Array<string>>
}

export const JobAgentSelfHostedContext = createContext<JobAgentSelfHostedContextValue>({
  agents: [],
  osFamilies: {},
})

export const useJobAgentSelfHostedContext = () => useContext(JobAgentSelfHostedContext)

const DELAY = 500

export const useJobAgentSelfHostedContextValue = () => {
  const [allAgents, refetch] = useRefetchableLazyLoadQuery<SelfHostedRequirementsQuery>(
    selfHostedRequirementsQuery,
    {},
  )

  useEffect(() => {
    let isOnSubscribe = true
    const handler = throttle(
      () => {
        if (isOnSubscribe) {
          isOnSubscribe = false
          return
        }
        refetch()
      },
      DELAY,
      {leading: true, trailing: true},
    )
    const unsubscribeOverallEvents = subscribeOnOverallEvents(
      REGULAR_OVERALL_AGENT_EVENT_TOPICS,
      handler,
    )
    return () => {
      unsubscribeOverallEvents()
      handler.cancel()
    }
  }, [refetch])

  const selfHostedAgents = useMemo(
    () =>
      allAgents.agentsRest?.agent?.filter(agent => {
        const properties = agent.properties?.property
        const jbHostedProperty = properties?.find(
          property => property.name === 'teamcity.agent.jbHosted',
        )
        const isJetBrainsHosted = jbHostedProperty?.value === 'true'

        return !isJetBrainsHosted
      }) ?? [],
    [allAgents.agentsRest?.agent],
  )

  const osFamilies = useMemo(() => {
    const result: Record<string, Array<string>> = {}

    selfHostedAgents.forEach(agent => {
      const properties = agent.properties?.property

      const osFamily = properties?.find(
        property => property.name === 'teamcity.agent.jvm.os.family',
      )?.value

      if (osFamily == null) {
        return
      }

      if (result[osFamily] == null) {
        result[osFamily] = []
      }

      const osName = properties?.find(property => property.name === 'teamcity.agent.os.name')?.value

      if (osName == null) {
        return
      }

      if (!result[osFamily]?.includes(osName)) {
        result[osFamily]?.push(osName)
      }
    })
    return result
  }, [selfHostedAgents])

  return useMemo(
    () => ({
      agents: selfHostedAgents,
      osFamilies,
    }),
    [selfHostedAgents, osFamilies],
  )
}
