import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {memo, Suspense} from 'react'

import SettingsBlock from '../../../../components/SettingsBlock/SettingsBlock'
import {isCloud} from '../../../../utils/featureToggles'
import styles from '../JobSteps/JobStep/JobStepRunInDocker/JobStepRunInDocker.module.css'

import JetBrainsHostedAgents from './JetBrainsHostedAgents/JetBrainsHostedAgents'
import {useJobAgentRequirement, useJobAgentRequirements} from './JobAgentRequirements.hooks'
import type {JobAgentRequirementsProps} from './JobAgentRequirements.types'
import JobAgentSelfHosted from './SelfHosted/JobAgentSelfHosted'
import JobAgentSelfHostedCloud from './SelfHosted/JobAgentSelfHostedCloud'

function JobAgentRequirements({jobId, cloudImagesQueryRef}: JobAgentRequirementsProps) {
  const {selectedCloudImage} = useJobAgentRequirements(jobId, cloudImagesQueryRef)
  const {isSelfHostedMode, handleSelfHostedClick, handleJetBrainsHosted} =
    useJobAgentRequirement(jobId)

  const renderCloudContent = (
    <>
      <ButtonGroup className={styles.modeToggle}>
        <Button
          className={styles.modeToggleButton}
          active={!isSelfHostedMode}
          onClick={handleJetBrainsHosted}
          height={ControlsHeight.M}
        >
          {'JetBrains-hosted'}
        </Button>
        <Button
          className={styles.modeToggleButton}
          active={isSelfHostedMode}
          onClick={handleSelfHostedClick}
          height={ControlsHeight.M}
        >
          {'Self-hosted'}
        </Button>
      </ButtonGroup>

      {isSelfHostedMode ? (
        <Suspense fallback={<LoaderInline data-suspense-fallback>{'Loading...'}</LoaderInline>}>
          <JobAgentSelfHostedCloud jobId={jobId} />
        </Suspense>
      ) : (
        <JetBrainsHostedAgents jobId={jobId} cloudImagesQueryRef={cloudImagesQueryRef} />
      )}
    </>
  )

  const renderContent = <JobAgentSelfHosted jobId={jobId} />

  return (
    <SettingsBlock
      id={'agent'}
      title={isCloud ? 'Run on' : 'Agent Requirements'}
      collapsedNote={
        selectedCloudImage && `${selectedCloudImage.label}, ${selectedCloudImage.details}`
      }
      collapsible
    >
      {isCloud ? renderCloudContent : renderContent}
    </SettingsBlock>
  )
}

export default memo(JobAgentRequirements)
