import type {AnchorProps} from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/list'
import List from '@jetbrains/ring-ui-built/components/list/list'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {memo, useCallback, useMemo, useState} from 'react'

import PopupMenu from '../../../../../../../../../common/Popup/PopupMenu.lazy'
import useBooleanState from '../../../../../../../hooks/useBooleanState'
import {isPipelinesEnabledInExclusiveMode} from '../../../../../../../utils/featureToggles'
import {useArchTypeRequirement} from '../ArchType/ArchTypeRequirement.hooks'
import ArchTypeFilter from '../ArchType/Filter/ArchTypeFilter'
import {useCPURequirement} from '../CPU/CPURequirement.hooks'
import CPUFilter from '../CPU/Filter/CPUFilter'
import CustomRequirementDialog from '../Custom/Dialog/CustomRequirementDialog'
import OSFilter from '../OS/Filter/OSFilter'
import {useOSRequirement} from '../OS/OSRequirement.hooks'
import RAMFilter from '../RAM/Filter/RAMFilter'
import {useRAMRequirement} from '../RAM/RAMRequirement.hooks'
import {directions} from '../SelfHostedRequirements.consts'
import type {SelfHostedRequirement} from '../SelfHostedRequirements.types'
import {
  isArchRequirement,
  isCpuRequirement,
  isOsFamilyRequirement,
  isRamRequirement,
  SelfHostedRequirementType,
} from '../SelfHostedRequirements.types'

import {getPopupModeIcon, SelfRequirementsPopupMode, toPopupMode} from './AddRequirement.types'

import styles from './AddRequirement.module.css'

interface Props {
  items: Array<SelfHostedRequirement>
  onAdd: (item: SelfHostedRequirement) => void
}

function AddRequirement(props: Props) {
  const {items, onAdd} = props
  const [isOpenDialog, openDialog, closeDialog] = useBooleanState(false)

  const [selectedMode, setMode] = useState(SelfRequirementsPopupMode.MAIN)
  const mainTypesItems = useMemo(
    () =>
      [
        ...(isPipelinesEnabledInExclusiveMode()
          ? [{check: isOsFamilyRequirement, type: SelfHostedRequirementType.OS}]
          : []),
        {check: isCpuRequirement, type: SelfHostedRequirementType.CPU_COUNT},
        {check: isArchRequirement, type: SelfHostedRequirementType.CPU_ARCH},
        {check: isRamRequirement, type: SelfHostedRequirementType.RAM_AMOUNT},
      ]
        .filter(({check}) => items.every(item => !check(item)))
        .map(({type}) => ({
          key: type,
          label: type,
          glyph: getPopupModeIcon(type),
          onClick: () => setMode(toPopupMode(type)),
        })),
    [items],
  )
  const mainItems: ReadonlyArray<ListDataItem> = useMemo(
    () => [
      ...mainTypesItems,
      {
        key: 'separator',
        rgItemType: List.ListProps.Type.SEPARATOR,
      },
      {
        className: styles.customRequirement,
        label: 'Add custom requirement',
        rgItemType: List.ListProps.Type.LINK,
        onClick: () => openDialog(),
      },
    ],
    [mainTypesItems, openDialog],
  )

  const {
    data: osData,
    currentOsFamilyRequirement: osFamilyRequirement,
    currentOsVersionRequirement: osVersionRequirement,
    reset: resetOs,
  } = useOSRequirement()
  const {
    data: archData,
    currentRequirement: archRequirement,
    reset: resetArch,
  } = useArchTypeRequirement()
  const {data: cpuData, currentRequirement: cpuRequirement, reset: resetCPU} = useCPURequirement()
  const {data: ramData, currentRequirement: ramRequirement, reset: resetRAM} = useRAMRequirement()

  const data: ReadonlyArray<ListDataItem> = useMemo(() => {
    switch (selectedMode) {
      case SelfRequirementsPopupMode.MAIN:
        return mainItems
      case SelfRequirementsPopupMode.OS:
        return osData
      case SelfRequirementsPopupMode.CPU_COUNT:
        return cpuData
      case SelfRequirementsPopupMode.CPU_ARCH:
        return archData
      case SelfRequirementsPopupMode.RAM_AMOUNT:
        return ramData
      default:
        return mainItems
    }
  }, [archData, cpuData, mainItems, osData, ramData, selectedMode])
  const activeIndex = useMemo(() => data.findIndex(item => item.rightGlyph != null), [data])

  const onHide = () => {
    if (osFamilyRequirement) {
      onAdd(osFamilyRequirement)

      if (osVersionRequirement) {
        onAdd(osVersionRequirement)
      }
    }

    if (archRequirement) {
      onAdd(archRequirement)
    }

    if (cpuRequirement) {
      onAdd(cpuRequirement)
    }

    if (ramRequirement) {
      onAdd(ramRequirement)
    }

    resetCPU()
    resetRAM()
    resetArch()
    resetOs()
    setMode(SelfRequirementsPopupMode.MAIN)
  }

  const anchor = useCallback(
    ({active}: AnchorProps) => {
      switch (selectedMode) {
        case SelfRequirementsPopupMode.MAIN:
          return (
            <IconButton
              icon={'add'}
              title={'Add requirement'}
              aria-label={'Add requirement'}
              withBorder
              height={ControlsHeight.M}
              active={active}
            >
              {'Add requirement'}
            </IconButton>
          )
        case SelfRequirementsPopupMode.OS:
          return (
            <OSFilter
              osVersionRequirement={osVersionRequirement}
              osFamilyRequirement={osFamilyRequirement}
              active={active}
            />
          )
        case SelfRequirementsPopupMode.CPU_ARCH:
          return <ArchTypeFilter value={archRequirement?.arch} active={active} />
        case SelfRequirementsPopupMode.RAM_AMOUNT:
          return <RAMFilter value={ramRequirement?.ram} active={active} />
        case SelfRequirementsPopupMode.CPU_COUNT:
          return <CPUFilter value={cpuRequirement?.cpu} active={active} />
        default:
          return null
      }
    },
    [
      selectedMode,
      osVersionRequirement,
      osFamilyRequirement,
      archRequirement?.arch,
      ramRequirement?.ram,
      cpuRequirement?.cpu,
    ],
  )

  return (
    <>
      {mainTypesItems.length > 0 ? (
        <Dropdown anchor={anchor} clickMode onHide={onHide}>
          <PopupMenu
            offset={4}
            directions={directions}
            data={data}
            activeIndex={activeIndex}
            minWidth={210}
          />
        </Dropdown>
      ) : (
        <IconButton
          data-test={'add-custom-requirement'}
          icon={'add'}
          title={'Add custom requirement'}
          aria-label={'Add custom requirement'}
          height={ControlsHeight.M}
          withBorder
          onClick={openDialog}
        >
          {'Add custom requirement'}
        </IconButton>
      )}
      {isOpenDialog && <CustomRequirementDialog show onSave={onAdd} onCloseAttempt={closeDialog} />}
    </>
  )
}

export default memo(AddRequirement)
