import type * as React from 'react'

import HelpDetails from '../../../../common/HelpDetails/HelpDetails'

import styles from './SummaryDetailsCardWrapperHeader.module.css'

type SummaryDetailsCardWrapperHeaderProps = {
  label?: string
  icon?: React.ReactNode
  info?: React.ReactNode
}

function SummaryDetailsCardWrapperHeader({
  icon,
  label,
  info,
}: SummaryDetailsCardWrapperHeaderProps) {
  return (
    <div className={styles.main}>
      {icon && <div className={styles.icon}>{icon}</div>}
      <div className={styles.labelWrapper}>
        {label && <div className={styles.label}>{label}</div>}
        {info && <HelpDetails>{info}</HelpDetails>}
      </div>
    </div>
  )
}

export default SummaryDetailsCardWrapperHeader
