import PipelineParametersSettingsBlock from '../../../../components/PipelineParametersSettingsBlock/PipelineParametersSettingsBlock'
import ParametersControlProvider from '../../../../contexts/ParametersControl/ParametersControlContext'

import {jobParametersSettingsBlockId} from './JobParameters.consts'
import useJobParameters from './useJobParameters'

function JobParameters() {
  const {
    jobParameters,
    settingsBlockTitle,
    deletedJobParameters,
    collapsedNote,
    parametersControlValue,
    isSettingsBlockCollapsible,
    jobParametersFormErrorMessage,
    clickEditJobParametersHandler,
  } = useJobParameters()

  return (
    <ParametersControlProvider value={parametersControlValue}>
      <PipelineParametersSettingsBlock
        title={settingsBlockTitle}
        blockId={jobParametersSettingsBlockId}
        collapsible={isSettingsBlockCollapsible}
        collapsedNote={collapsedNote}
        error={jobParametersFormErrorMessage}
        onEdit={clickEditJobParametersHandler}
        parameters={jobParameters}
        deleted={deletedJobParameters}
      />
    </ParametersControlProvider>
  )
}

export default JobParameters
