import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {ReactNode} from 'react'

import {useIsDebugRunning} from '../../EditPipelinePage/EditPipelinePage.hooks'
import {runnersNameMap} from '../../EditPipelinePage/SettingsSidebarContent/JobSettingsSidebar/JobSteps/JobStep/JobStepJsonForm/JobStepJsonForm.const'
import EditButton from '../EditButton/EditButton'
import HighlighterTextView from '../HighlighterTextField/HighlighterTextView'
import RunnerIconButton from '../RunnerIconButton/RunnerIconButton'

import RunnerSummarizePreviewLoader from './RunnerSummarizePreviewLoader'

import styles from './RunnerSummarizePreview.module.css'

export type RunnerSummarizePreviewProp = {
  runner: string
  name?: string
  title: string
  text?: string
  deleted?: boolean
  onDelete?: () => void
  onEdit?: () => void
  onRestore?: () => void
  onClone?: () => void
  error?: ReactNode
  loading?: boolean
  bottomContent?: ReactNode
}

function RunnerSummarizePreview({
  runner,
  name = '',
  title,
  text,
  deleted,
  onRestore,
  onDelete,
  onEdit,
  onClone,
  error,
  loading,
  bottomContent,
}: RunnerSummarizePreviewProp) {
  const containerClassNames = classNames(styles.container, {
    [styles.deleted]: deleted,
  })
  const isShowControlButton = !deleted
  const isShowDetails = !loading && !deleted && text
  const isReadonly = useIsDebugRunning()

  return (
    <div className={containerClassNames}>
      <div className={styles.containerHeader}>
        <div className={styles.icon}>
          <RunnerIconButton className={styles.runnerIconButton} icon={runner} />
        </div>
        <div className={styles.info}>
          <div className={styles.name}>
            {`${title}: `} <span className={styles.subName}>{runnersNameMap[runner]}</span>
          </div>
          <div className={styles.type}>{name}</div>
        </div>
        {!isReadonly && (
          <div className={styles.controls}>
            {deleted && (
              <IconButton
                className={styles.actionButton}
                icon="update"
                title="Restore"
                aria-label="Restore"
                onClick={onRestore}
              />
            )}
            {isShowControlButton && (
              <div className={styles.controlButtons}>
                <IconButton
                  className={styles.actionButton}
                  icon="duplicate"
                  title="Clone"
                  aria-label="Clone"
                  onClick={onClone}
                />
                <EditButton
                  className={styles.actionButton}
                  title="Edit"
                  aria-label="Edit"
                  onClick={onEdit}
                />
                <IconButton
                  className={styles.actionButton}
                  icon="trash"
                  title="Delete"
                  aria-label="Delete"
                  onClick={onDelete}
                />
              </div>
            )}
          </div>
        )}
      </div>
      {loading && <RunnerSummarizePreviewLoader />}
      {isShowDetails && (
        <pre className={styles.details}>
          <HighlighterTextView value={text} multiline />
        </pre>
      )}
      {!!error && <div className={styles.error}>{error}</div>}
      {!isReadonly && !deleted && !!bottomContent && (
        <div className={styles.bottomContent}>{bottomContent}</div>
      )}
    </div>
  )
}

export default RunnerSummarizePreview
