import type {SingleSelectAttrs} from '@jetbrains/ring-ui-built/components/select/select'
import Select from '@jetbrains/ring-ui-built/components/select/select'
import classNames from 'classnames'
import type {ReactNode, Ref} from 'react'
import {forwardRef, useContext} from 'react'

import {DisabledContext} from '../../../contexts/DisabledContext'

import styles from './SidebarSelect.module.css'

type Props = SingleSelectAttrs & {
  containerClassName?: string
  helperText?: ReactNode
}

function SidebarSelect(
  {className, helperText, containerClassName, ...otherProps}: Props,
  forwardedRef?: Ref<Select>,
) {
  const isDisabled = useContext(DisabledContext)
  return (
    <div className={containerClassName}>
      <Select
        ref={forwardedRef}
        renderOptimization={false}
        {...otherProps}
        className={classNames(styles.select, className)}
        size={Select.Size.FULL}
        disabled={isDisabled}
      />
      {helperText && <span className={styles.selectedLabel}>{helperText}</span>}
    </div>
  )
}

export default forwardRef(SidebarSelect)
