import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import {memo} from 'react'

import useJobAllowReuse from './JobAllowReuse.hooks'
import type {JobAllowReuseProps} from './JobAllowReuse.types'

import HelpDetails from 'src/components/common/HelpDetails/HelpDetails'

function JobAllowReuse({jobId}: JobAllowReuseProps) {
  const {handlerJobAllowReuseToggle, jobAllowReuse} = useJobAllowReuse(jobId)

  return (
    <Toggle onChange={handlerJobAllowReuseToggle} checked={jobAllowReuse}>
      {'Reuse Job Results'}
      <HelpDetails>
        {
          'TeamCity Pipelines will re-use the results of the last job run, if it was successful and no other commits have been made since'
        }
      </HelpDetails>
    </Toggle>
  )
}

export default memo(JobAllowReuse)
