import type React from 'react'
import {useRef, useEffect} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../hooks/pipeline'
import {StepTypes} from '../../../../types'
import {getDraftJobs, getJobEnableDependencyCache} from '../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../slices/EditPipelinePage.slices'

function useJobEnableDependencyCache(jobId: string) {
  const hasNotAppliedYetRef = useRef<Record<string, boolean>>({
    [jobId]: false,
  })
  const hasNotAppliedYet = hasNotAppliedYetRef.current[jobId]
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const jobEnableDependencyCache = useAppSelector(getJobEnableDependencyCache(jobId, pipelineId))
  const deletedSteps = useAppSelector(
    state => state.pipelines.pipelineDraft[pipelineId]?.deleted?.steps?.[jobId],
  )
  const stepList = useAppSelector(state => getDraftJobs(state, pipelineId)?.[jobId]?.steps)
  const supportsDependencyCache = (step: string): boolean =>
    step === StepTypes.MAVEN || step === StepTypes.GRADLE
  const isApplicable = !!stepList?.filter(
    ({type}, index) => !deletedSteps?.includes(index) && supportsDependencyCache(type),
  ).length
  const isDependencyCacheEnabled = !!jobEnableDependencyCache && isApplicable
  const handlerEnableDependencyCacheToggle = ({
    currentTarget,
  }: React.ChangeEvent<HTMLInputElement>) => {
    dispatch(
      pipelineDraft.actions.toggleEnableDependencyCache({
        id: pipelineId,
        jobId,
        value: currentTarget.checked,
      }),
    )
  }

  useEffect(() => {
    if (isApplicable && !hasNotAppliedYet) {
      dispatch(
        pipelineDraft.actions.toggleEnableDependencyCache({
          id: pipelineId,
          jobId,
          value: true,
        }),
      )
      hasNotAppliedYetRef.current[jobId] = true
    }
  }, [dispatch, hasNotAppliedYet, jobId, pipelineId, isApplicable])

  return {
    handlerEnableDependencyCacheToggle,
    isDependencyCacheEnabled,
    isApplicable,
  }
}

export default useJobEnableDependencyCache
