import {memo} from 'react'

import HighlighterTextFieldProvider from '../../../../../components/HighlighterTextField/HighlighterTextFieldContext'
import {HighlightSpotId} from '../../../../../components/HighlighterTextField/HighlighterTextFieldContext.types'

import SelfHostedEmpty from './Empty/SelfHostedEmpty'
import {
  JobAgentSelfHostedContext,
  useJobAgentSelfHostedContextValue,
} from './JobAgentSelfHosted.contexts'
import SelfHostedRequirements from './Requirements/SelfHostedRequirements'

interface Props {
  jobId: string
}

function JobAgentSelfHostedCloud(props: Props) {
  const {jobId} = props
  const value = useJobAgentSelfHostedContextValue()

  return value.agents.length === 0 ? (
    <SelfHostedEmpty />
  ) : (
    <JobAgentSelfHostedContext.Provider value={value}>
      <HighlighterTextFieldProvider spot={{[HighlightSpotId.AGENT_REQUIREMENTS]: true}}>
        <SelfHostedRequirements jobId={jobId} />
      </HighlighterTextFieldProvider>
    </JobAgentSelfHostedContext.Provider>
  )
}

export default memo(JobAgentSelfHostedCloud)
