import SettingsBlock from '../../../../components/SettingsBlock/SettingsBlock'
import JobFilesPublication from '../JobFilesPublication/JobFilesPublication'
import JobOutputParameters from '../JobOutputParameters/JobOutputParameters'

import {settingsBlockId, settingsBlockTitle} from './JobOutputs.const'
import JobOutputsCollapsedNote from './JobOutputsCollapsedNote'
import JobOutputsSettingsBlockCustomActions from './JobOutputsSettingsBlockCustomActions/JobOutputsSettingsBlockCustomActions'
import useJobOutputs from './useJobOutputs'

import styles from './JobOutputs.module.css'

function JobOutputs() {
  const {isCollapsible, addJobOutputsButtonRef} = useJobOutputs()

  return (
    <SettingsBlock
      id={settingsBlockId}
      collapsible={isCollapsible}
      title={settingsBlockTitle}
      collapsedNote={<JobOutputsCollapsedNote />}
      collapsibleClassName={styles.settingsBlock}
      onAddClick={() => addJobOutputsButtonRef?.current?.click()}
      customActions={anchor => (
        <JobOutputsSettingsBlockCustomActions
          anchor={<div ref={addJobOutputsButtonRef}>{anchor}</div>}
        />
      )}
      details={
        'Add output parameters and files to be shared or published after the job completion.'
      }
    >
      <JobOutputParameters />
      <JobFilesPublication />
    </SettingsBlock>
  )
}

export default JobOutputs
