import {Fragment} from 'react'

import styles from './CompatibleAgentList.module.css'

type CompatibleAgenReasonsColumnProps = {
  compatible: boolean
  unmetReqirements: Array<{parameter: string; predicate: string; name: string; value: string}>
  unresolvedParameters: Array<{origin: string; parameter: string}>
  invalidRunnerParameters: Array<{
    parameter: string
    reason: string
  }>
}

function CompatibleAgenReasonsColumn({
  compatible,
  unmetReqirements,
  unresolvedParameters,
  invalidRunnerParameters,
}: CompatibleAgenReasonsColumnProps) {
  if (compatible) {
    return '-'
  }

  return (
    <Fragment>
      {!!unresolvedParameters.length && (
        <div className={styles.incompatibleReasonsContainer}>
          <div>{'Unresolved parameters:'}</div>
          <ul className={styles.incompatibleReasons}>
            {unresolvedParameters.map(parameter => (
              <li key={parameter.parameter}>
                <b>{parameter.parameter}</b>
                {` must have a value (referenced in `}
                <b>{`${parameter.origin} )`}</b>
              </li>
            ))}
          </ul>
        </div>
      )}
      {!!invalidRunnerParameters.length && (
        <div className={styles.incompatibleReasonsContainer}>
          <div>{'Invalid step parameters:'}</div>
          <ul className={styles.incompatibleReasons}>
            {invalidRunnerParameters.map(parameter => (
              <li key={parameter.parameter}>{parameter.reason}</li>
            ))}
          </ul>
        </div>
      )}
      {!!unmetReqirements.length && (
        <div className={styles.incompatibleReasonsContainer}>
          <div>{'Unmet requirements:'}</div>
          <ul className={styles.incompatibleReasons}>
            {unmetReqirements.map(requirement => (
              <li key={requirement.parameter}>
                {[requirement.name, requirement.predicate, requirement.value]
                  .filter(value => value != null)
                  .join(' ')}
              </li>
            ))}
          </ul>
        </div>
      )}
    </Fragment>
  )
}

export default CompatibleAgenReasonsColumn
