import Button from '@jetbrains/ring-ui-built/components/button/button'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {memo, useMemo} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../../../../hooks/react-redux'
import useEventCallback from '../../../../../../../../../hooks/useEventCallback'
import {usePipelineId} from '../../../../../../hooks/pipeline'
import useBooleanState from '../../../../../../hooks/useBooleanState'
import {isPipelineCompatibilityAgentsEnabled} from '../../../../../../utils/featureToggles'
import {getRunsOn} from '../../../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../../../slices/EditPipelinePage.slices'
import {useAgentCompatibilities} from '../../JobAgentRequirements.hooks'
import SelfHostedAlert from '../Alert/SelfHostedAlert'
import SelfHostedCompatibleAgentDialog from '../Compatible/SelfHostedCompatibleAgentDialog'
import AgentInstallButton from '../InstallAgent/InstallAgent'

import AddRequirement from './Add/AddRequirement'
import ArchTypeRequirement from './ArchType/ArchTypeRequirement'
import CPURequirement from './CPU/CPURequirement'
import CustomRequirement from './Custom/CustomRequirement'
import OSRequirement from './OS/OSRequirement'
import RAMRequirement from './RAM/RAMRequirement'
import {
  anyVersion,
  isArchRequirement,
  isCpuRequirement,
  isCustomRequirement,
  isOsFamilyRequirement,
  isOsVersionRequirement,
  isRamRequirement,
} from './SelfHostedRequirements.types'
import type {SelfHostedRequirement} from './SelfHostedRequirements.types'

import styles from './SelfHostedRequirements.module.css'

interface Props {
  jobId: string
}

function SelfHostedRequirements(props: Props) {
  const {jobId} = props
  const id = usePipelineId()

  const runsOn = useAppSelector(state => getRunsOn(jobId, id)(state))
  const items = useMemo(() => (typeof runsOn === 'object' ? runsOn['self-hosted'] : []), [runsOn])

  const {selfHostedAgents, selfHostedCompatibleAgents, isLoading} = useAgentCompatibilities(
    jobId,
    items,
  )

  const [isOpenCompatibleDialog, openCompatibleDialog, closeCompatibleDialog] =
    useBooleanState(false)

  const dispatch = useAppDispatch()
  const onAdd = useEventCallback((requirement: SelfHostedRequirement) => {
    if (isOsVersionRequirement(requirement) && requirement['os-version'] === anyVersion) {
      dispatch(
        pipelineDraft.actions.removeSelfHostedRequirement({
          id,
          jobId,
          requirement,
        }),
      )
    } else {
      dispatch(
        pipelineDraft.actions.addSelfHostedRequirements({
          id,
          jobId,
          requirement,
        }),
      )
    }
  })
  const onChange = useEventCallback((prev: SelfHostedRequirement, next: SelfHostedRequirement) => {
    if (isOsVersionRequirement(next) && next['os-version'] === anyVersion) {
      dispatch(
        pipelineDraft.actions.removeSelfHostedRequirement({
          id,
          jobId,
          requirement: prev,
        }),
      )
    } else {
      dispatch(
        pipelineDraft.actions.changeSelfHostedRequirement({
          id,
          jobId,
          prev,
          next,
        }),
      )
    }
  })
  const onRemove = useEventCallback((requirement: SelfHostedRequirement) =>
    dispatch(
      pipelineDraft.actions.removeSelfHostedRequirement({
        id,
        jobId,
        requirement,
      }),
    ),
  )

  const osVersionRequirement = items.find(isOsVersionRequirement)

  return (
    <div className={styles.content}>
      <div className={styles.filterContainer}>
        {items.map(requirement => {
          if (isArchRequirement(requirement)) {
            return (
              <ArchTypeRequirement
                key={'arch'}
                requirement={requirement}
                onChange={onChange}
                onRemove={onRemove}
              />
            )
          } else if (isRamRequirement(requirement)) {
            return (
              <RAMRequirement
                key={'ram'}
                requirement={requirement}
                onChange={onChange}
                onRemove={onRemove}
              />
            )
          } else if (isCpuRequirement(requirement)) {
            return (
              <CPURequirement
                key={'cpu'}
                requirement={requirement}
                onChange={onChange}
                onRemove={onRemove}
              />
            )
          } else if (isCustomRequirement(requirement)) {
            return (
              <CustomRequirement
                key={requirement.name}
                requirement={requirement}
                onChange={onChange}
                onRemove={onRemove}
              />
            )
          } else if (isOsFamilyRequirement(requirement)) {
            return (
              <OSRequirement
                key={'os'}
                osFamilyRequirement={requirement}
                osVersionRequirement={osVersionRequirement}
                onAdd={onAdd}
                onChange={onChange}
                onRemove={onRemove}
              />
            )
          }

          return null
        })}
        <AddRequirement items={items} onAdd={onAdd} />
      </div>
      {isPipelineCompatibilityAgentsEnabled && (
        <>
          {!isLoading && selfHostedCompatibleAgents.length === 0 && <SelfHostedAlert />}
          <div className={styles.footer}>
            {isLoading ? (
              <LoaderInline />
            ) : (
              <>
                <Button
                  className={styles.button}
                  title={'Compatible agents'}
                  aria-label={'Compatible agents'}
                  height={ControlsHeight.M}
                  onClick={openCompatibleDialog}
                  inline
                >
                  {`Compatible agents: ${selfHostedCompatibleAgents.length} out of ${selfHostedAgents.length}`}
                </Button>
                {isOpenCompatibleDialog && (
                  <SelfHostedCompatibleAgentDialog
                    show
                    agents={selfHostedAgents}
                    onCloseAttempt={closeCompatibleDialog}
                  />
                )}
                <AgentInstallButton inline />
              </>
            )}
          </div>
        </>
      )}
    </div>
  )
}

export default memo(SelfHostedRequirements)
