import {useJobStepFormContext} from '../JobStep/JobStepFormContext/JobStepFormContext'

const noDetailsDefaultText = 'No details'

function useJobStepGenerateDefaultSummarize(jobId: string, stepIndex: number) {
  const {step, editStepId, buildStepsDescription, isBuildStepsDescriptionLoading} =
    useJobStepFormContext()
  const buildStepDescription = buildStepsDescription?.jobs?.[jobId]?.steps?.[stepIndex]
  const stepSummarizeText =
    step?.['script-content'] ?? step?.['shell-script'] ?? noDetailsDefaultText
  const summarizeText = buildStepDescription ? buildStepDescription : stepSummarizeText
  const isSummarizeTextLoading =
    (editStepId == null && isBuildStepsDescriptionLoading) ||
    (Number(editStepId) === stepIndex && isBuildStepsDescriptionLoading)

  return {
    summarizeText,
    isSummarizeTextLoading,
  }
}

export default useJobStepGenerateDefaultSummarize
