import CheckmarkIcon from '@jetbrains/icons/checkmark.svg'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/list'
import {useMemo, useState} from 'react'

import type {ArchTypeRequirement} from '../SelfHostedRequirements.types'
import {ArchType} from '../SelfHostedRequirements.types'

interface Props {
  requirement?: ArchTypeRequirement
}
export const useArchTypeRequirement = (props?: Props) => {
  const {requirement} = props ?? {}
  const [nextRequirement, setNextRequirement] = useState<ArchTypeRequirement | null>(null)
  const currentRequirement = nextRequirement ?? requirement

  const data: ReadonlyArray<ListDataItem> = useMemo(
    () =>
      Object.values(ArchType).map(arch => ({
        label: arch,
        key: arch,
        rightGlyph: currentRequirement?.arch === arch ? CheckmarkIcon : null,
        onClick: () =>
          setNextRequirement({
            arch,
          }),
      })),
    [currentRequirement?.arch],
  )

  const reset = () => setNextRequirement(null)

  return {
    data,
    currentRequirement,
    reset,
  }
}
