import {skipToken} from '@reduxjs/toolkit/query'
import {graphql, useFragment} from 'react-relay'

import {restApi} from '../../../../../../../../../services/rest'
import {isTemporaryHideFailedJobStateEditMode} from '../../../../../../utils/featureToggles'
import {useDraftStepError, useLastRun} from '../../../../../EditPipelinePage.hooks'
import {useJobStepFormContext} from '../../JobStep/JobStepFormContext/JobStepFormContext'

import type {useJobStepRunnerSummarizeErrorPreviewRunFragment$key} from './__generated__/useJobStepRunnerSummarizeErrorPreviewRunFragment.graphql'

const lastRunFragment = graphql`
  fragment useJobStepRunnerSummarizeErrorPreviewRunFragment on Build {
    status
    id
  }
`

function useJobStepRunnerSummarizeErrorPreview() {
  const {jobId, pipelineHeadBuildTypeKey, originalIndex: stepIndex} = useJobStepFormContext()
  const runKey = useLastRun(jobId, pipelineHeadBuildTypeKey)
  const run = useFragment<useJobStepRunnerSummarizeErrorPreviewRunFragment$key>(
    lastRunFragment,
    runKey,
  )
  const failureId = run?.status !== 'SUCCESS' ? run?.id : null
  const listStepsIndex = stepIndex + 1
  const stepErrorMessage = useDraftStepError({
    stepIndex,
  })
  const {buildAnchor, pointType} = restApi.endpoints.getBuildTimeline.useQuery(
    failureId != null ? {buildId: failureId} : skipToken,
    {
      selectFromResult: ({data}) => {
        const {buildAnchor, type} =
          data?.stages.find(stage => stage.name.startsWith(`Step ${listStepsIndex}/`))?.point ?? {}
        return {buildAnchor, pointType: type}
      },
    },
  )
  const isShowError =
    stepErrorMessage || (buildAnchor && failureId && !isTemporaryHideFailedJobStateEditMode)

  return {
    isShowError,
    stepErrorMessage,
    failureId,
    buildAnchor,
    pointType,
  }
}

export default useJobStepRunnerSummarizeErrorPreview
