import {memo} from 'react'

import FilterRequirement from '../../Filter/FilterRequirement'
import styles from '../../SelfHostedRequirements.module.css'
import type {OSFamilyRequirement, OSVersionRequirement} from '../../SelfHostedRequirements.types'

import MonitorIcon from 'src/svg/monitor.svg'

interface Props {
  osFamilyRequirement?: OSFamilyRequirement
  osVersionRequirement?: OSVersionRequirement
  onRemoveClick?: () => void
  active: boolean
}

function OSFilter(props: Props) {
  const {osFamilyRequirement, osVersionRequirement, onRemoveClick, active} = props

  return (
    <FilterRequirement
      data-test={'os-filter-requirement'}
      icon={MonitorIcon}
      active={active}
      onRemoveClick={onRemoveClick}
    >
      {`OS is `}
      {osFamilyRequirement && (
        <span className={styles.bold}>
          {osVersionRequirement?.['os-version']?.startsWith(osFamilyRequirement?.['os-family'])
            ? osVersionRequirement?.['os-version']
            : `${osFamilyRequirement?.['os-family']} ${osVersionRequirement?.['os-version']}`}
        </span>
      )}
    </FilterRequirement>
  )
}

export default memo(OSFilter)
