import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import type {ReactNode} from 'react'
import {memo} from 'react'

import {conditionSign, conditionText} from '../../SelfHostedRequirements.types'
import type {CustomRequirement} from '../../SelfHostedRequirements.types'

import styles from './CustomRequirementTooltip.module.css'

import Tooltip from 'src/components/common/Tooltip/Tooltip'

interface Props {
  requirement: CustomRequirement
  children: ReactNode
}

function CustomRequirementTooltip(props: Props) {
  const {requirement, children} = props
  return (
    <Tooltip
      popupProps={{
        directions: [Directions.TOP_CENTER, Directions.BOTTOM_CENTER],
        className: styles.tooltip,
      }}
      title={
        <div className={styles.content} data-test={'custom-requirement-tooltip'}>
          <SvgIcon icon={'info'} />
          <div className={styles.requirement}>
            <div>{'Custom requirement'}</div>
            <div className={styles.parameter} data-test={'parameter'}>
              {requirement.parameter}{' '}
              <span className={styles.condition} data-test={'condition'}>
                {conditionSign[requirement.requirement] ??
                  conditionText[requirement.requirement].toLocaleLowerCase()}
              </span>{' '}
              {requirement.value ? requirement.value : null}
            </div>
          </div>
        </div>
      }
      onClick={e => e.stopPropagation()}
    >
      {children}
    </Tooltip>
  )
}

export default memo(CustomRequirementTooltip)
