import type {AnchorProps} from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {memo, useCallback} from 'react'

import useEventCallback from '../../../../../../../../../../hooks/useEventCallback'
import PopupMenu from '../../../../../../../../../common/Popup/PopupMenu.lazy'
import {directions} from '../SelfHostedRequirements.consts'
import type {CpuCountRequirement, SelfHostedRequirement} from '../SelfHostedRequirements.types'

import {useCPURequirement} from './CPURequirement.hooks'
import CPUFilter from './Filter/CPUFilter'

interface Props {
  requirement: CpuCountRequirement
  onChange: (prevRequirement: SelfHostedRequirement, nextRequirement: SelfHostedRequirement) => void
  onRemove: (requirement: CpuCountRequirement) => void
}

function CPURequirementComponent(props: Props) {
  const {requirement, onChange, onRemove} = props
  const {data, currentRequirement, reset} = useCPURequirement({
    requirement,
  })

  const handleRemoveClick = useEventCallback(() => {
    onRemove(requirement)
  })

  const anchor = useCallback(
    ({active}: AnchorProps) => (
      <CPUFilter
        value={currentRequirement?.cpu}
        active={active}
        onRemoveClick={handleRemoveClick}
      />
    ),
    [currentRequirement, handleRemoveClick],
  )

  const onHide = () => {
    if (currentRequirement) {
      onChange(requirement, currentRequirement)
    }
    reset()
  }

  return (
    <Dropdown data-test={'cpu-requirement'} anchor={anchor} clickMode onHide={onHide}>
      <PopupMenu offset={4} directions={directions} data={data} minWidth={210} />
    </Dropdown>
  )
}

export default memo(CPURequirementComponent)
