import CheckmarkIcon from '@jetbrains/icons/checkmark.svg'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/list'
import List from '@jetbrains/ring-ui-built/components/list/list'
import Select from '@jetbrains/ring-ui-built/components/select/select'
import {useMemo, useState} from 'react'

import {useJobAgentSelfHostedContext} from '../../JobAgentSelfHosted.contexts'
import styles from '../SelfHostedRequirements.module.css'
import type {OSFamilyRequirement, OSVersionRequirement} from '../SelfHostedRequirements.types'
import {anyVersion} from '../SelfHostedRequirements.types'

interface Props {
  osFamilyRequirement?: OSFamilyRequirement
  osVersionRequirement?: OSVersionRequirement
}

const anyVersionRequirement = {
  'os-version': anyVersion,
} as OSVersionRequirement

export const useOSRequirement = (props?: Props) => {
  const {osFamilyRequirement, osVersionRequirement} = props ?? {}
  const [nextOsFamilyRequirement, setNextOsFamilyRequirement] =
    useState<OSFamilyRequirement | null>(null)
  const [nextOsVersionRequirement, setNextOsVersionRequirement] =
    useState<OSVersionRequirement | null>(null)

  const currentOsFamilyRequirement = nextOsFamilyRequirement ?? osFamilyRequirement
  const currentOsVersionRequirement =
    nextOsVersionRequirement ?? osVersionRequirement ?? anyVersionRequirement

  const {osFamilies} = useJobAgentSelfHostedContext()

  const osFamilyItems = useMemo(
    () =>
      Object.keys(osFamilies).map(os => ({
        label: os,
        key: os,
        // glyph: osFamilyIcon[os],
        rightGlyph: currentOsFamilyRequirement?.['os-family'] === os ? CheckmarkIcon : null,
      })),
    [currentOsFamilyRequirement, osFamilies],
  )

  const osFamilyVersionItems = useMemo(() => {
    const items = []

    if (currentOsFamilyRequirement && osFamilies[currentOsFamilyRequirement['os-family']]) {
      items.push(
        ...osFamilies[currentOsFamilyRequirement?.['os-family']].map(item => ({
          label: item,
          key: item,
          rightGlyph: currentOsVersionRequirement?.['os-version'] === item ? CheckmarkIcon : null,
        })),
      )
    }

    items.push({
      label: anyVersion,
      key: anyVersion,
      rightGlyph: currentOsVersionRequirement?.['os-version'] === anyVersion ? CheckmarkIcon : null,
    })

    return items
  }, [currentOsFamilyRequirement, currentOsVersionRequirement, osFamilies])

  const data: ReadonlyArray<ListDataItem> = useMemo(
    () => [
      {
        rgItemType: List.ListProps.Type.CUSTOM,
        key: 'family',
        template: (
          <>
            <div className={styles.label}>{'OS Family'}</div>
            <Select
              label={'OS Family'}
              data={osFamilyItems}
              selected={osFamilyItems.find(
                item => item.key === currentOsFamilyRequirement?.['os-family'],
              )}
              onSelect={item => {
                if (item) {
                  setNextOsFamilyRequirement({
                    ['os-family']: item?.key,
                  })
                  setNextOsVersionRequirement(anyVersionRequirement)
                }
              }}
            />
          </>
        ),
      },
      {
        rgItemType: List.ListProps.Type.CUSTOM,
        key: 'version',
        template: (
          <>
            <div className={styles.label}>{'OS Version'}</div>
            <Select
              label={'OS Version'}
              selected={osFamilyVersionItems.find(
                item => item.key === currentOsVersionRequirement?.['os-version'],
              )}
              data={osFamilyVersionItems}
              onSelect={item => {
                if (item) {
                  setNextOsVersionRequirement({
                    'os-version': item.key,
                  })
                }
              }}
            />
          </>
        ),
      },
    ],
    [currentOsFamilyRequirement, currentOsVersionRequirement, osFamilyItems, osFamilyVersionItems],
  )

  const reset = () => {
    setNextOsFamilyRequirement(null)
    setNextOsVersionRequirement(null)
  }

  return {
    data,
    currentOsFamilyRequirement,
    currentOsVersionRequirement,
    reset,
  }
}
