import classNames from 'classnames'
import {useMemo} from 'react'
import type {SyntheticEvent, MouseEvent} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {useJobId} from '../../../../EditPipelinePage.hooks'
import {isPipelineFormOpened} from '../../../../EditPipelinePage.selectors'
import {pipelineForm} from '../../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../../slices/EditPipelinePage.slices.types'
import {getRepositoryFolder, getRepositoryName} from '../JobRepositories.utils'

import styles from './JobRepository.module.css'

function useJobRepository(
  url: string,
  path?: string,
  checked?: boolean,
  main?: boolean,
  deleted?: boolean,
  onChange?: (value: {enabled: boolean; path?: string}) => void,
) {
  const pipelineId = usePipelineId()
  const jobId = useJobId()
  const formParams = {pipelineId, jobId, id: url, type: FormType.REPOSITORY}
  const isEditPath = useAppSelector(state => isPipelineFormOpened(state, formParams))
  const toggleClassNames = classNames(styles.toggle, {
    [styles.toggleDeleted]: deleted,
  })
  const repositoryName = getRepositoryName(url)
  const repositoryFolder = main ? '' : getRepositoryFolder(url)
  const repositoryPath = useMemo(() => {
    if (path) {
      return path
    } else if (main) {
      return ''
    }

    return getRepositoryFolder(url)
  }, [main, path, url])
  const dispatch = useAppDispatch()
  const editPathButtonClickHandler = isEditPath
    ? undefined
    : (e: MouseEvent<HTMLDivElement>) => {
        e.preventDefault()
        e.stopPropagation()
        dispatch(pipelineForm.actions.open(formParams))
      }
  const closeFormHandler = (e: MouseEvent<HTMLButtonElement>) => {
    e.preventDefault()
    e.stopPropagation()
    dispatch(pipelineForm.actions.close(formParams))
  }
  const isShowPathInput = checked
  const toggleFormHandler = ({currentTarget}: SyntheticEvent<{checked: boolean}>) =>
    onChange?.({
      path: path ?? getRepositoryFolder(url),
      enabled: currentTarget.checked,
    })
  const changePathHandler = (value?: string) =>
    onChange?.({
      path: value,
      enabled: !!checked,
    })

  return {
    isEditPath,
    toggleClassNames,
    repositoryName,
    isShowPathInput,
    repositoryPath,
    repositoryFolder,
    editPathButtonClickHandler,
    closeFormHandler,
    changePathHandler,
    toggleFormHandler,
  }
}

export default useJobRepository
