import type React from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../hooks/pipeline'
import {getJobAllowReuse, getOriginalPipelineSettings} from '../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../slices/EditPipelinePage.slices'

function useJobAllowReuse(jobId: string) {
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const savedJobAllowReuse =
    useAppSelector(getOriginalPipelineSettings(pipelineId))?.jobs?.[jobId]?.['allow-reuse'] !==
    false

  const jobAllowReuse = useAppSelector(getJobAllowReuse(jobId, pipelineId))
  const handlerJobAllowReuseToggle = ({currentTarget}: React.ChangeEvent<HTMLInputElement>) => {
    dispatch(
      pipelineDraft.actions.toggleJobAllowReuse({
        id: pipelineId,
        jobId,
        value: currentTarget.checked,
      }),
    )
  }
  const isUnsaved = savedJobAllowReuse !== jobAllowReuse

  return {
    handlerJobAllowReuseToggle,
    jobAllowReuse,
    isUnsaved,
  }
}

export default useJobAllowReuse
