import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import isEmpty from 'lodash/isEmpty'
import * as React from 'react'

import EditButton from '../../../../../components/EditButton/EditButton'
import {checkoutDirectoryLabel} from '../JobRepositories.consts'

import type {JobRepositoryProps} from './JobRepository.types'
import JobRepositoryForm from './JobRepositoryForm/JobRepositoryForm'
import useJobRepository from './useJobRepository'

import styles from './JobRepository.module.css'

function JobRepository({
  path,
  checked,
  deleted,
  last,
  main,
  name,
  url,
  branch,
  isExternal,
  onChange,
}: JobRepositoryProps) {
  const {
    isEditPath,
    toggleClassNames,
    repositoryName,
    isShowPathInput,
    repositoryPath,
    repositoryFolder,
    editPathButtonClickHandler,
    changePathHandler,
    closeFormHandler,
    toggleFormHandler,
  } = useJobRepository(url, path, checked, main, deleted, onChange)
  const isDisabledToggle = last || deleted

  return (
    <div className={styles.repositoryWrapper}>
      <Toggle
        className={toggleClassNames}
        disabled={isDisabledToggle}
        checked={checked}
        onChange={toggleFormHandler}
      >
        <div>{isExternal ? name : repositoryName}</div>
      </Toggle>
      {branch && <div className={styles.folder}>{`Default branch: ${branch}`}</div>}
      {isShowPathInput && (
        <div
          role="presentation"
          className={styles.folderContainer}
          onClick={editPathButtonClickHandler}
        >
          {!isEditPath && (
            <React.Fragment>
              {repositoryPath ? (
                <div
                  className={styles.folder}
                >{`${checkoutDirectoryLabel}: ${repositoryPath}`}</div>
              ) : (
                <div
                  className={styles.folder}
                >{`${checkoutDirectoryLabel}: <checkout directory>`}</div>
              )}
            </React.Fragment>
          )}
          {isEditPath && (
            <JobRepositoryForm
              value={path}
              placeholder={isEmpty(repositoryFolder) ? '<checkout directory>' : repositoryFolder}
              onChange={changePathHandler}
              onClose={closeFormHandler}
            />
          )}
          {!isEditPath && (
            <EditButton className={styles.editButtom} iconClassName={styles.editIcon} />
          )}
        </div>
      )}
    </div>
  )
}

export default JobRepository
