import {Fragment} from 'react'

import useJobFilesPublicationStore from '../JobFilesPublication/useJobFilesPublicationStore'
import useJobOutputParametersStore from '../JobOutputParameters/useJobOutputParametersStore'

function JobOutputsCollapsedNote() {
  const {summaryNote: filesPublicationSummaryNote} = useJobFilesPublicationStore()
  const {summaryNote: outputParametersSummaryNote} = useJobOutputParametersStore()

  return (
    <Fragment>
      {outputParametersSummaryNote && (
        <div>{`Output parameters: ${outputParametersSummaryNote}`}</div>
      )}
      {filesPublicationSummaryNote && <div>{`Shared files: ${filesPublicationSummaryNote}`}</div>}
    </Fragment>
  )
}

export default JobOutputsCollapsedNote
