import type {Draft} from 'immer'
import {produce} from 'immer'

import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {memo, useCallback, useMemo} from 'react'
import {arrayMove, List} from 'react-movable'
import type {RenderItemParams} from 'react-movable/lib/types'
import {useSearchParams} from 'react-router'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import SettingsBlock from '../../../../components/SettingsBlock/SettingsBlock'
import type {pipelineHeadBuildTypeFragment$key} from '../../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineId} from '../../../../hooks/pipeline'
import {pipelinesApi} from '../../../../services/pipelinesApi'
import type {Step} from '../../../../types'
import {StepTypes} from '../../../../types'
import {useIsDebugRunning} from '../../../EditPipelinePage.hooks'
import {getSteps} from '../../../EditPipelinePage.selectors'
import {pipelineDraft, pipelineErrors} from '../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'
import {sideBarNavigatiobSearchParam} from '../../SettingsSidebarContent.const'

import useJobStepsStoredValue from './hooks/useJobStepsStoredValue'
import JobStepFormProvider from './JobStep/JobStepFormContext/JobStepFormContext'
import JobStepRunnerSummarizePreview from './JobStepRunnerSummarizePreview/JobStepRunnerSummarizePreview'
import useJobStepRunnerSummarize from './JobStepRunnerSummarizePreview/useJobStepRunnerSummarize'
import {getStepPreset} from './JobSteps.utils'
import JobStepSelectRunner from './JobStepSelectRunner/JobStepSelectRunner'

import styles from './JobSteps.module.css'

type Props = {
  jobId: string
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
  stepIndex?: number
}

const orderListTransitionDuration = 100

function JobSteps({jobId, stepIndex, pipelineHeadBuildTypeKey}: Props) {
  const pipelineId = usePipelineId()
  const {
    editStepId,
    loadBuildStepDescription,
    buildStepsDescription,
    isBuildStepsDescriptionLoading,
  } = useJobStepRunnerSummarize()
  const jobStepListStore = useAppSelector(state => getSteps(state, pipelineId, jobId))
  const stepList = useMemo(() => jobStepListStore ?? [], [jobStepListStore])
  const isReadonly = useIsDebugRunning()
  const {addStoredJobStep} = useJobStepsStoredValue(stepList, jobId)
  const reordered = useAppSelector(
    state => state.pipelines.pipelineDraft[pipelineId]?.reordered?.steps?.[jobId],
  )
  const [searchParams, setSearchParams] = useSearchParams()
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const order = stepList?.map((_, i) => reordered?.[i] ?? i)
  const dispatch = useAppDispatch()
  const updateSteps = useCallback(
    (recipe: (draft: Draft<Step[]>) => void, index: number) => {
      const steps = produce(stepList ?? [], recipe)
      const storedStep = steps[index]

      addStoredJobStep(storedStep, index)

      dispatch(
        pipelineDraft.actions.setSteps({
          id: pipelineId,
          jobId,
          steps,
        }),
      )
    },
    [stepList, addStoredJobStep, dispatch, pipelineId, jobId],
  )
  const onStepPropertiesChange = useCallback(
    (index: number, properties: Array<{name: string; value: string | null}>) => {
      updateSteps((draft: Draft<Step[]>) => {
        const step = draft[index]

        for (const {name, value} of properties) {
          if (value == null) {
            delete step[name]
            dispatch(
              pipelineErrors.actions.clear({
                pipelineId,
                jobId,
                formType: FormType.STEP,
                formId: index,
                fieldName: name,
              }),
            )
          } else {
            step[name] = value
          }
        }
      }, index)
    },
    [dispatch, jobId, pipelineId, updateSteps],
  )
  const cloneStepHandler = useCallback(
    (index: number) => {
      updateSteps((draft: Draft<Step[]>) => {
        const stepItem = draft[index]
        const cloneName = stepItem.name ? `${stepItem.name} (clone)` : ''

        draft.splice(index + 1, 0, {...stepItem, name: cloneName})
      }, index)

      loadBuildStepDescription()
    },
    [loadBuildStepDescription, updateSteps],
  )
  const addStep = useCallback(
    (type?: string) => {
      setSearchParams({
        ...searchParamsObject,
        [sideBarNavigatiobSearchParam.step]: stepList.length.toString(),
      })

      updateSteps((draft: Draft<Step[]>) => {
        let step: Step = {type: type ?? StepTypes.CLI}
        const stepPreset = getStepPreset(type)

        if (stepPreset) {
          step = {
            ...step,
            ...stepPreset,
          }
        }

        draft.push(step)
      }, stepList.length)
    },
    [searchParamsObject, setSearchParams, stepList.length, updateSteps],
  )
  const hasSteps = Boolean(stepList?.length)
  const {jobRunners} = pipelinesApi.endpoints.getPipelineRunnersJsonFromXMLs.useQuery(undefined, {
    selectFromResult: ({data}) => ({
      jobRunners: data,
    }),
  })
  const jobRunnersKey = jobRunners ? Object.keys(jobRunners) : undefined
  const renderItem = ({
    value: originalIndex = 0,
    index = 0,
    props,
  }: Partial<RenderItemParams<number>>) => {
    const step = stepList[originalIndex!]
    const valueProvider = {
      step,
      pipelineHeadBuildTypeKey,
      jobId,
      jobRunners: jobRunners ?? {},
      originalIndex,
      stepIndex: index,
      onStepPropertiesChange,
      editStepId,
      buildStepsDescription,
      isBuildStepsDescriptionLoading,
    }
    const stepNumber = `Step ${index + 1}`
    const draggable = !isReadonly && stepList.length > 1

    return (
      step && (
        <div {...props} key={props?.key} className={styles.stepItem}>
          <div className={styles.header}>
            <JobStepFormProvider value={valueProvider}>
              {draggable && (
                <IconButton
                  data-movable-handle
                  className={styles.handle}
                  icon="drag"
                  title="Use drag-and-drop to reorder steps"
                />
              )}
              <JobStepRunnerSummarizePreview
                jobId={jobId}
                originalIndex={originalIndex}
                title={stepNumber}
                name={step.name}
                runner={step.type}
                cloneStepHandler={cloneStepHandler}
              />
            </JobStepFormProvider>
          </div>
        </div>
      )
    )
  }

  if (Number.isInteger(stepIndex)) {
    return renderItem({value: stepIndex, index: stepIndex})
  }

  return (
    <SettingsBlock id={'steps'} title={'Steps'} collapsible childrenVisible>
      {hasSteps ? (
        <>
          {order.length > 1 ? (
            <div className={styles.stepWrapper}>
              <List
                disabled={isReadonly}
                onChange={({oldIndex, newIndex}) =>
                  dispatch(
                    pipelineDraft.actions.reorderSteps({
                      id: pipelineId,
                      jobId,
                      order: arrayMove(order, oldIndex, newIndex),
                    }),
                  )
                }
                values={order}
                transitionDuration={orderListTransitionDuration}
                renderList={({children, props}) => <div {...props}>{children}</div>}
                renderItem={renderItem}
              />
            </div>
          ) : (
            <div className={styles.stepWrapper}>{renderItem({value: 0, index: 0})}</div>
          )}
          {!isReadonly && <JobStepSelectRunner runners={jobRunnersKey} onSelect={addStep} />}
        </>
      ) : (
        <JobStepSelectRunner runners={jobRunnersKey} onSelect={addStep} />
      )}
    </SettingsBlock>
  )
}

export default memo(JobSteps)
