import {useState} from 'react'
import {useSearchParams} from 'react-router'

import {sideBarNavigatiobSearchParam} from '../../SettingsSidebarContent.const'

import {maxListItemLimitAmount} from './JobFilesPublication.const'
import useJobFilesPublicationStore from './useJobFilesPublicationStore'

function useJobFilesPublication() {
  const {
    getIsKeyDelete,
    filesPublication,
    deleteFilesPublicationHandler,
    restoreFilesPublicationHandler,
  } = useJobFilesPublicationStore()
  const clickDeleteFilePublicationButtonClickHandler = (index: number) => () =>
    deleteFilesPublicationHandler(index)
  const clickRestoreFilePublicationButtonClickHandler = (index: number) => () =>
    restoreFilesPublicationHandler(index)
  const filesPublicationLength = filesPublication.length
  const [listItemLimit, setListItemLimit] = useState<number>(maxListItemLimitAmount)
  const isShowMoreButton = filesPublicationLength > maxListItemLimitAmount
  const clickShowMoreButtonHandler = () => {
    const itemLimit =
      listItemLimit === maxListItemLimitAmount ? filesPublicationLength : maxListItemLimitAmount

    setListItemLimit(itemLimit)
  }
  const isBlockExpanded = listItemLimit === filesPublicationLength
  const [searchParams, setSearchParams] = useSearchParams()
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const clickEditJobSharedFilesHandler = () =>
    setSearchParams({
      ...searchParamsObject,
      [sideBarNavigatiobSearchParam.sharedFiles]: 'true',
    })

  return {
    listItemLimit,
    isBlockExpanded,
    getIsKeyDelete,
    isShowMoreButton,
    filesPublication,
    filesPublicationLength,
    clickShowMoreButtonHandler,
    clickEditJobSharedFilesHandler,
    clickRestoreFilePublicationButtonClickHandler,
    clickDeleteFilePublicationButtonClickHandler,
  }
}

export default useJobFilesPublication
