import {memo} from 'react'

import FilterRequirement from '../../Filter/FilterRequirement'
import styles from '../../SelfHostedRequirements.module.css'
import type {ArchType} from '../../SelfHostedRequirements.types'

import ArchIcon from 'src/svg/cpu-chip-arch.svg'

interface Props {
  value?: ArchType
  onRemoveClick?: () => void
  active: boolean
}

function ArchTypeFilter(props: Props) {
  const {value, onRemoveClick, active} = props
  return (
    <FilterRequirement
      data-test={'arch-type-filter-requirement'}
      active={active}
      onRemoveClick={onRemoveClick}
      icon={ArchIcon}
    >
      {`CPU arch is `}
      {value && <span className={styles.bold}>{value}</span>}
    </FilterRequirement>
  )
}

export default memo(ArchTypeFilter)
