import type {MouseEvent} from 'react'

import EditSettingsForm from '../../../../../../components/EditSettingsForm/EditSettingsForm'
import {checkoutDirectoryLabel} from '../../JobRepositories.consts'
import styles from '../JobRepository.module.css'

import useJobRepositoryForm from './useJobRepositoryForm'

import Input, {Size} from 'src/components/pages/PipelinesPages/components/Input'

type JobRepositoryFormProps = {
  value?: string
  placeholder?: string
  onChange: (value?: string) => void
  onClose: (e: MouseEvent<HTMLButtonElement>) => void
}

function JobRepositoryForm({value = '', placeholder, onChange, onClose}: JobRepositoryFormProps) {
  const {inputFolderRef, changeInputPathHandler} = useJobRepositoryForm(onChange)

  return (
    <EditSettingsForm inline onConfirmClick={onClose}>
      <div className={styles.formContainer}>
        <div className={styles.folder}>{`${checkoutDirectoryLabel}:`}</div>
        <div className={styles.inputFolder}>
          <Input
            inputRef={inputFolderRef}
            value={value}
            placeholder={placeholder}
            size={Size.FULL}
            autoComplete={'off'}
            onChange={changeInputPathHandler}
          />
        </div>
      </div>
    </EditSettingsForm>
  )
}

export default JobRepositoryForm
