import {graphql} from 'react-relay'

export const selfHostedRequirementsQuery = graphql`
  query SelfHostedRequirementsQuery {
    agentsRest(locator: "defaultFilter:false") {
      agent {
        id
        name
        typeId
        environment {
          osName
          osType
        }
        properties {
          property {
            name
            value
          }
        }
      }
    }
  }
`
