import SettingsBlock from '../../../../components/SettingsBlock/SettingsBlock'

import {jobRepositoriesSettingsBlockId, mainRepositoryName} from './JobRepositories.consts'
import JobRepositoriesDetails from './JobRepositoriesDetails'
import JobRepository from './JobRepository/JobRepository'
import useJobRepositories from './useJobRepositories'

import styles from './JobRepositories.module.css'

function JobRepositories() {
  const {
    settingsBlockTitle,
    deletedRepositoriesSet,
    pipelineVcsRoots,
    shortNoticeRepositories,
    mainRepositoryId,
    jobRepositoriesMap,
    isMainRepositoryDisabled,
    isMainRepositoryNone,
    jobRepositoryChangePath,
  } = useJobRepositories()

  return (
    <SettingsBlock
      collapsible
      id={jobRepositoriesSettingsBlockId}
      title={settingsBlockTitle}
      details={<JobRepositoriesDetails />}
      collapsedNote={shortNoticeRepositories}
      collapsibleClassName={styles.repositories}
    >
      {pipelineVcsRoots?.map(({id, url, name, isExternal, branch}) => {
        const isMainRepository = id === mainRepositoryId
        if (!isMainRepository && !url) {
          return null
        }

        const minNumberRepositories = 2
        const repositoryUrl = isMainRepository ? mainRepositoryName : url
        const repository = jobRepositoriesMap.get(repositoryUrl)
        const isOnlyMainRepository =
          isMainRepository &&
          ((!isMainRepositoryNone && jobRepositoriesMap.size === 1) ||
            jobRepositoriesMap.size === 0)
        const isEnabledRepository = !!repository?.enabled
        const isChecked = isMainRepository ? !isMainRepositoryDisabled : isEnabledRepository
        const isDeleted = deletedRepositoriesSet.has(repositoryUrl)
        const isLast =
          isOnlyMainRepository ||
          (isMainRepositoryDisabled &&
            jobRepositoriesMap.size === minNumberRepositories &&
            isEnabledRepository)

        return (
          <JobRepository
            key={repositoryUrl}
            checked={isChecked}
            path={repository?.path}
            url={url}
            name={name}
            last={isLast}
            deleted={isDeleted}
            branch={branch}
            main={isMainRepository}
            isExternal={isExternal}
            onChange={jobRepositoryChangePath(repositoryUrl)}
          />
        )
      })}
    </SettingsBlock>
  )
}

export default JobRepositories
