import Link from '@jetbrains/ring-ui-built/components/link/link'

import AlertInfoMessage from '../../../../../components/AlertInfoMessage/AlertInfoMessage'
import useBooleanState from '../../../../../hooks/useBooleanState'
import type {AgentCompatibility} from '../../../../../services/pipelinesApi.types'
import SelfHostedCompatibleAgentDialog from '../SelfHosted/Compatible/SelfHostedCompatibleAgentDialog'

import styles from './JetBrainsHostedAgents.module.css'

type JJetBrainsHostedAgentsSelectWarningProps = {
  agents?: AgentCompatibility[]
}

function JetBrainsHostedAgentsSelectWarning({
  agents = [],
}: JJetBrainsHostedAgentsSelectWarningProps) {
  const [
    isShowReasonsIncompatibility,
    clickShowReasonsIncompatibilityButtonHandler,
    clickCloseReasonsIncompatibilityButtonHandler,
  ] = useBooleanState(false)

  return (
    <AlertInfoMessage className={styles.alertInfoMessage} type="warning">
      {'Agent incompatible with requirements. Select another suitable JetBrains-hosted agent. '}
      <Link
        className={styles.compatibleAgentDetailButton}
        title={'Show reasons for incompatibility'}
        aria-label={'Show reasons for incompatibility'}
        onClick={clickShowReasonsIncompatibilityButtonHandler}
      >
        {'Show reasons for incompatibility'}
      </Link>
      {isShowReasonsIncompatibility && (
        <SelfHostedCompatibleAgentDialog
          show
          isCloudHosted
          agents={agents}
          onCloseAttempt={clickCloseReasonsIncompatibilityButtonHandler}
        />
      )}
    </AlertInfoMessage>
  )
}

export default JetBrainsHostedAgentsSelectWarning
