import {getGuessedGitProtocol} from '../../../../components/PipelineForm/PipelineForm.utils'
import {ProtocolVcsRepository} from '../../../../components/VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm.consts'
import type {NewVcsRootDto} from '../../../../services/pipelinesApi.types'

export const getRepositoryName = (url?: string) => {
  const sshGit = getGuessedGitProtocol(url) === ProtocolVcsRepository.SSH
  const defaultName = 'none'

  if (sshGit) {
    return url ?? defaultName
  }

  try {
    if (url) {
      const {host, pathname} = new URL(url)

      if (pathname) {
        return `${host}${pathname}`
      }
    }
  } catch (e) {
    return defaultName
  }

  return defaultName
}

export const getRepositoryFolder = (url?: string) => {
  try {
    if (url) {
      const {pathname = ''} = new URL(url)
      const lastPath = pathname.split('/').pop()

      return lastPath ?? undefined
    }
  } catch (e) {
    return undefined
  }

  return undefined
}

export const getRepositoryShortNotice = (vcsRoot: NewVcsRootDto) => {
  if (vcsRoot.isExternal) {
    return vcsRoot.name
  }

  return vcsRoot.url ?? vcsRoot.port
}
