import CheckmarkIcon from '@jetbrains/icons/checkmark.svg'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/list'
import List from '@jetbrains/ring-ui-built/components/list/list'
import {useMemo, useState} from 'react'

import {Size} from '../../../../../../../components/Input'
import Input from '../../../../../../../components/Input/Input'
import requirementStyles from '../SelfHostedRequirements.module.css'
import type {RamAmountRequirement} from '../SelfHostedRequirements.types'
import {ramAmountList} from '../SelfHostedRequirements.types'

import styles from './RAMRequirement.module.css'

interface Props {
  requirement?: RamAmountRequirement
}
export const useRAMRequirement = (props?: Props) => {
  const {requirement} = props ?? {}
  const [nextRequirement, setNextRequirement] = useState<RamAmountRequirement | null>(null)
  const currentRequirement = nextRequirement ?? requirement

  const data: ReadonlyArray<ListDataItem> = useMemo(
    () => [
      ...ramAmountList.map(ram => ({
        label: ram,
        key: ram,
        rightGlyph: currentRequirement?.ram === ram ? CheckmarkIcon : null,
        onClick: () => {
          setNextRequirement({
            ram,
          })
        },
      })),
      {
        rgItemType: List.ListProps.Type.CUSTOM,
        template: (
          <div className={styles.ram}>
            <Input
              type="number"
              placeholder="Number"
              className={styles.ramInput}
              inputClassName={requirementStyles.numberInput}
              spellCheck={false}
              size={Size.FULL}
              value={
                currentRequirement?.ram?.substring(0, currentRequirement?.ram.length - 2) ?? ''
              }
              min={1}
              onChange={e => {
                setNextRequirement({
                  ram: `${e.currentTarget.value}GB`,
                })
              }}
              autoComplete="off"
            />
            {'GB'}
          </div>
        ),
      },
    ],
    [currentRequirement?.ram],
  )

  const reset = () => setNextRequirement(null)

  return {
    data,
    currentRequirement,
    reset,
  }
}
