import Button from '@jetbrains/ring-ui-built/components/button/button'
import {LabelType} from '@jetbrains/ring-ui-built/components/control-label/control-label'
import Dialog, {type DialogAttrs} from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {Header, Content} from '@jetbrains/ring-ui-built/components/island/island'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import Select, {type SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import type React from 'react'
import {useCallback, memo, useMemo, useState} from 'react'

import useEventCallback from '../../../../../../../../../../../hooks/useEventCallback'
import {resolveHelpURL} from '../../../../../../../../../../../utils/url'
import {Size} from '../../../../../../../../components/Input'
import Input from '../../../../../../../../components/Input/Input'
import useParametersResolve from '../../../../../../../../hooks/useParametersResolve'
import type {CustomRequirement} from '../../SelfHostedRequirements.types'
import {
  conditionText,
  conditionSign,
  CustomRequirementCondition,
} from '../../SelfHostedRequirements.types'

import {
  getParameterSuggestionList,
  getValueSuggestionList,
  onChangeSelect,
} from './CustomRequirementDialog.utils'

import styles from './CustomRequirementDialog.module.css'

interface Props {
  requirement?: CustomRequirement
  onSave: (nextRequirement: CustomRequirement) => void
}

function CustomRequirementDialog(props: Props & DialogAttrs) {
  const {requirement, onSave, ...restProps} = props
  const {onCloseAttempt} = restProps

  const [name, setName] = useState<string | undefined>(requirement?.name)
  const [parameter, setParameter] = useState<string | undefined>(requirement?.parameter)
  const [selectedCondition, setCondition] = useState(
    requirement?.requirement ?? CustomRequirementCondition.EXISTS,
  )
  const [value, setValue] = useState<string | undefined>(
    requirement?.requirement !== CustomRequirementCondition.EXISTS &&
      requirement?.requirement !== CustomRequirementCondition.NOT_EXISTS
      ? requirement?.value
      : undefined,
  )

  const conditions = useMemo(
    () =>
      Object.values(CustomRequirementCondition).map(condition => ({
        key: condition,
        label: conditionText[condition],
        rightNodes: conditionSign[condition] && (
          <Text className={styles.sign}>{conditionSign[condition]}</Text>
        ),
      })),
    [],
  )

  const isValueRequired =
    selectedCondition !== CustomRequirementCondition.EXISTS &&
    selectedCondition !== CustomRequirementCondition.NOT_EXISTS
  const isDisabled = !name || !parameter || (isValueRequired && !value)

  const handleSaveClick = useEventCallback((event: React.MouseEvent<HTMLElement>) => {
    if (isDisabled) {
      return
    }

    if (isValueRequired) {
      onSave({
        requirement: selectedCondition,
        name,
        parameter,
        value,
      })
    } else {
      onSave({
        requirement: selectedCondition,
        name,
        parameter,
      })
    }

    onCloseAttempt?.(event)
  })

  const {parametersResolve} = useParametersResolve(parameter ?? '', true)
  const suggestionList = useMemo(
    () => getParameterSuggestionList(parametersResolve, parameter),
    [parameter, parametersResolve],
  )

  const onChangeParameterSelect = useCallback((selected: SelectItem | null) => {
    onChangeSelect(selected, setParameter)
  }, [])
  const onChangeValueSelect = useCallback((selected: SelectItem | null) => {
    onChangeSelect(selected, setValue)
  }, [])

  const valueSuggestionList = useMemo(() => {
    const paremeter = parametersResolve.find(item => item.name === parameter)
    return paremeter ? getValueSuggestionList(paremeter.values) : []
  }, [parameter, parametersResolve])

  return (
    <Dialog
      data-test={'custom-requirement-dialog'}
      trapFocus
      showCloseButton
      closeButtonInside
      contentClassName={styles.dialog}
      {...restProps}
    >
      <Header>{requirement ? 'Update custom requirement' : 'Add custom requirement'}</Header>
      <Content className={styles.content} scrollableWrapperClassName={styles.scrollableContent}>
        <div className={styles.innerContent}>
          <Input
            data-test={'display-name'}
            label={'Display name'}
            placeholder={'Requirement name'}
            type="text"
            spellCheck={false}
            size={Size.FULL}
            value={name ?? ''}
            onChange={e => setName(e.currentTarget.value)}
          />
          <Select
            data-test={'parameter'}
            className={styles.parameterNameSelect}
            size={Size.FULL}
            type={Select.Type.INPUT}
            directions={[Directions.BOTTOM_RIGHT]}
            label={'Parameter'}
            labelType={LabelType.FORM}
            inputPlaceholder={'Agent parameter name'}
            selected={parameter ? {label: parameter, key: parameter} : null}
            filter={{value: parameter, fn: () => true}}
            data={suggestionList}
            onChange={onChangeParameterSelect}
            renderOptimization={false}
            disableScrollToActive
            hideArrow
            allowAny
            clear
          />
          <Text className={styles.hint} info>
            {'Read more '}
            <Link
              target="_blank"
              href={resolveHelpURL('configuring-build-parameters.html')}
              rel="noreferrer"
            >
              {`Agent parameters`}
            </Link>
          </Text>
          <Select
            data-test={'condition'}
            size={Select.Size.AUTO}
            className={styles.conditionalSelect}
            label={'Condition'}
            data={conditions}
            selected={conditions.find(item => item.key === selectedCondition)}
            onSelect={item => {
              if (item) {
                setCondition(item.key)
              }
            }}
          />
          {selectedCondition !== CustomRequirementCondition.EXISTS &&
            selectedCondition !== CustomRequirementCondition.NOT_EXISTS && (
              <Select
                className={styles.valueSelect}
                data-test={'value'}
                size={Size.FULL}
                type={Select.Type.INPUT}
                directions={[Directions.BOTTOM_RIGHT]}
                label={''}
                inputPlaceholder={'Value'}
                selected={value ? {label: value, key: value} : null}
                filter={{value, fn: () => true}}
                data={valueSuggestionList}
                onChange={onChangeValueSelect}
                renderOptimization={false}
                disableScrollToActive
                hideArrow
                allowAny
                clear
              />
            )}
        </div>
        <div className={styles.actions}>
          <Button data-test={'save'} primary disabled={isDisabled} onClick={handleSaveClick}>
            {'Save'}
          </Button>
          <Button data-test={'cancel'} onClick={onCloseAttempt}>
            {'Cancel'}
          </Button>
        </div>
      </Content>
    </Dialog>
  )
}

export default memo(CustomRequirementDialog)
