import Link from '@jetbrains/ring-ui-built/components/link/link'
import classNames from 'classnames'
import {memo, useMemo} from 'react'

import HelpDetails from '../../../../../../../common/HelpDetails/HelpDetails'
import useMapAgentCompatibilities from '../../../../../hooks/useMapAgentCompatibilities'
import {isPipelineCompatibilityAgentsEnabled} from '../../../../../utils/featureToggles'
import SidebarSelect from '../../../SidebarSelect/SidebarSelect'
import {linkCloudImageHardwareDoc} from '../JobAgentRequirements.consts'
import {useJobAgentRequirements} from '../JobAgentRequirements.hooks'
import JobAgentRequirementsSelectLabel from '../JobAgentRequirementsSelectLabel'

import type {Props} from './JetBrainsHostedAgents.types'
import JetBrainsHostedAgentsSelectWarning from './JetBrainsHostedAgentsSelectWarning'

import styles from './JetBrainsHostedAgents.module.css'

function JetBrainsHostedAgents(props: Props) {
  const {jobId, cloudImagesQueryRef} = props
  const {agents, label, isSelected, isFiltered, selectedCloudImage, handlerCloudImageSelect} =
    useJobAgentRequirements(jobId, cloudImagesQueryRef)
  const {cloudImageAgentCompatibilities, isCurrentAgentIncompatible} = useMapAgentCompatibilities()
  const selectDataAgetns = useMemo(
    () =>
      agents.map(agent => {
        const agentCompatible = cloudImageAgentCompatibilities?.find(
          ({agent: {name}}) => name === agent.key,
        )
        const rightNodes =
          agentCompatible && isPipelineCompatibilityAgentsEnabled ? (
            <JobAgentRequirementsSelectLabel compatible={agentCompatible.compatible} />
          ) : null

        return {...agent, rightNodes}
      }),
    [agents, cloudImageAgentCompatibilities],
  )
  const ButtonSelectedIcon = useMemo(
    () => (
      <div className={styles.selectedIcon}>
        {selectedCloudImage?.glyph && <selectedCloudImage.glyph />}
      </div>
    ),
    [selectedCloudImage],
  )
  const selectHelpText = isCurrentAgentIncompatible ? (
    <JetBrainsHostedAgentsSelectWarning agents={cloudImageAgentCompatibilities} />
  ) : (
    selectedCloudImage?.details
  )

  return (
    <>
      <div className={styles.container}>
        <SidebarSelect
          data={selectDataAgetns}
          selectedLabel={ButtonSelectedIcon}
          filter={isFiltered}
          popupClassName={styles.selectPopup}
          buttonClassName={classNames({
            [styles.selectButton]: isSelected,
            [styles.selectButtonWarning]: isCurrentAgentIncompatible,
          })}
          label={label}
          containerClassName={styles.selectContainer}
          selected={selectedCloudImage}
          helperText={selectHelpText}
          onSelect={handlerCloudImageSelect}
        />
        <HelpDetails className={styles.info}>
          {
            'If your build requires extra tools, you can install them on JetBrains-hosted agents via the Script runner commands, or run your Jobs in a Docker container.'
          }
          <Link
            className={styles.hardwareDocLink}
            target="_blank"
            href={linkCloudImageHardwareDoc}
            rel="noreferrer"
          >
            {'Show installed software'}
          </Link>
        </HelpDetails>
      </div>
    </>
  )
}

export default memo(JetBrainsHostedAgents)
