import plur from 'plur'
import {useCallback, useMemo} from 'react'
import {useSearchParams} from 'react-router'

import {HighlightSpotId} from '../../../../components/HighlighterTextField/HighlighterTextFieldContext.types'
import {sideBarNavigatiobSearchParam} from '../../SettingsSidebarContent.const'

import useJobParametersStore from './useJobParametersStore'

function useJobParameters() {
  const {
    jobParameters,
    formSpotParamId,
    formErrorSpotId,
    jobParametersKeys,
    renamedJobParameters,
    jobParametersLength,
    deletedJobParameters,
    existingJobParametersLength,
    jobParametersFormErrorMessage,
    changeNameHandler,
    changeValueHandler,
    restoreParametersHandler,
    deleteParametersHandler,
    confirmParametersHandler,
  } = useJobParametersStore()
  const parametersControlValue = useMemo(
    () => ({
      prefix: 'env.',
      parameters: jobParameters,
      renamedParameters: renamedJobParameters,
      formSpotParamId,
      formErrorSpotId,
      valueHighlightSpotId: HighlightSpotId.PARAMETER,
      onNameChange: changeNameHandler,
      onValueChange: changeValueHandler,
      onRestore: restoreParametersHandler,
      onDelete: deleteParametersHandler,
      onConfirm: confirmParametersHandler,
    }),
    [
      changeNameHandler,
      changeValueHandler,
      confirmParametersHandler,
      deleteParametersHandler,
      formErrorSpotId,
      formSpotParamId,
      jobParameters,
      renamedJobParameters,
      restoreParametersHandler,
    ],
  )
  const [searchParams, setSearchParams] = useSearchParams()
  const isSettingsBlockCollapsible = !!jobParametersLength
  const settingsBlockTitle = existingJobParametersLength
    ? plur('Job parameter', existingJobParametersLength)
    : 'No job parameters'
  const collapsedNote = useMemo(
    () =>
      jobParametersKeys
        .filter(key => !deletedJobParameters?.includes(key))
        .map(key => `${renamedJobParameters?.[key] ?? key}=${jobParameters[key]}`)
        .join(', '),
    [deletedJobParameters, jobParameters, jobParametersKeys, renamedJobParameters],
  )
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const clickEditJobParametersHandler = useCallback(
    () =>
      setSearchParams({
        ...searchParamsObject,
        [sideBarNavigatiobSearchParam.parameters]: 'true',
      }),
    [searchParamsObject, setSearchParams],
  )

  return {
    jobParameters,
    deletedJobParameters,
    settingsBlockTitle,
    collapsedNote,
    isSettingsBlockCollapsible,
    jobParametersFormErrorMessage,
    parametersControlValue,
    clickEditJobParametersHandler,
  }
}

export default useJobParameters
