import Link from '@jetbrains/ring-ui-built/components/link/link'
import {memo} from 'react'

import AlertInfoMessage from '../../../../../../components/AlertInfoMessage/AlertInfoMessage'
import useBooleanState from '../../../../../../hooks/useBooleanState'
import {useAuthorizablePoolId} from '../../JobAgentRequirements.hooks'
import InstallAgentDialog from '../InstallDialog/InstallAgentDialog'

import styles from './SelfHostedAlert.module.css'

function SelfHostedAlert() {
  const [isOpenDialog, openDialog, closeDialog] = useBooleanState(false)
  const authorizablePoolId = useAuthorizablePoolId()
  const canAuthorize = authorizablePoolId != null

  return (
    <>
      <AlertInfoMessage type="warning" className={styles.container} data-test={'self-hosted-alert'}>
        {canAuthorize ? (
          <div>
            {`None of the agents satisfy existing agent requirements. Edit the requirements or `}
            <Link
              className={styles.button}
              title={'Install self-hosted agent'}
              aria-label={'Install self-hosted agent'}
              onClick={openDialog}
            >
              {'Install a compatible self-hosted agent'}
            </Link>
          </div>
        ) : (
          <div>{`None of the agents satisfy existing agent requirements. Edit the requirements`}</div>
        )}
      </AlertInfoMessage>
      {isOpenDialog && canAuthorize && (
        <InstallAgentDialog poolId={authorizablePoolId} onCloseAttempt={closeDialog} />
      )}
    </>
  )
}

export default memo(SelfHostedAlert)
