import {getBuild} from 'src/selectors'

export const useRunDuration = (runId?: number) => {
  const startDate = useAppSelector(state => getBuild(state, runId)?.startDate)
  const finishDate = useAppSelector(state => getBuild(state, runId)?.finishDate)

  return useTimeSelector(now => {
    if (startDate != null && finishDate != null) {
      return differenceInSeconds(parseISO(finishDate), parseISO(startDate))
    }

    if (startDate != null) {
      return differenceInSeconds(now, parseISO(startDate))
    }

    return 0
  })
}

const THRESHOLD = 30
export const useRunRemainingTime = (runId?: number) => {
  const left = useAppSelector(state => getBuild(state, runId)?.['running-info']?.leftSeconds)

  /* eslint-disable @typescript-eslint/no-magic-numbers */
  const [estimatedFinishDate, setEstimatedFinishDate] = useState<number | null>(null)

  useEffect(() => {
    if (estimatedFinishDate == null && left != null) {
      setEstimatedFinishDate(Date.now() + left * 1000)
    }
  }, [estimatedFinishDate, left])

  return useTimeSelector(now => {
    if (estimatedFinishDate == null || left == null) {
      return 0
    }

    if (left === 0) {
      return left
    }

    const diff = Math.max(differenceInSeconds(estimatedFinishDate, now), 0)
    if (Math.abs(diff - left) >= THRESHOLD) {
      setEstimatedFinishDate(Date.now() + left * 1000)
    }

    return diff
  })
}

export const useTimeInQueue = (runId?: number) => {
  const startDate = useAppSelector(state => getBuild(state, runId)?.startDate)
  const queuedDate = useAppSelector(state => getBuild(state, runId)?.queuedDate)

  return useTimeSelector(now => {
    if (startDate != null && queuedDate != null) {
      return differenceInSeconds(parseISO(startDate), parseISO(queuedDate))
    }

    if (queuedDate != null) {
      return differenceInSeconds(now, parseISO(queuedDate))
    }

    return 0
  })
}

export const useOptimizedPercent = (
  duration?: number | null,
  optimizedDuration: number | null = 0,
) => {
  if (!optimizedDuration || !duration) {
    return null
  }
  const fraction = optimizedDuration / (duration + optimizedDuration)
  const value = Math.round(fraction * HUNDRED_PERCENT)
  if (value > HUNDRED_PERCENT) {
    return HUNDRED_PERCENT
  }
  if (value < 0) {
    return null
  }
  return value
}

export const useOptimizations = (
  appliedOptimizations?: Optimization[],
  parallelized?: boolean | null,
) => {
  const optimizations = useMemo(() => {
    const result = appliedOptimizations ? [...appliedOptimizations] : []
    if (parallelized) {
      result.push({
        name: Optimizations.PARALLEL_TESTING,
        value: 0,
        type: OptimizationType.DURATION,
      })
    }
    return result
  }, [appliedOptimizations, parallelized])

  // adding hardcoded missing optimizations
  const possibleOptimizations = useMemo(
    () =>
      POSSIBLE_OPTIMIZATIONS.filter(
        ({name: optimizationName}) => !optimizations?.find(({name}) => name === optimizationName),
      ),
    [optimizations],
  )

  return {
    optimizations,
    possibleOptimizations,
  }
}

const useDisplayDate = (buildId?: number) => {
  const startDate = useAppSelector(state => getBuild(state, buildId)?.startDate)
  const finishDate = useAppSelector(state => getBuild(state, buildId)?.finishDate)
  const isAutodetectTimeZone = useIsAutodetectTimeZone()

  let dateText = startDate ? displayDate(startDate, isAutodetectTimeZone, true) : ''
  if (startDate && finishDate) {
    let showOnlyTime = false
    const parsedStartDate = parseDateToObj(startDate, isAutodetectTimeZone)
    const parsedFinishDate = parseDateToObj(finishDate, isAutodetectTimeZone)

    if (parsedStartDate.isSame(parsedFinishDate, 'day')) {
      showOnlyTime = true
    }

    const finishDateText = `${displayDate(finishDate, isAutodetectTimeZone, true, !showOnlyTime)}`
    dateText += ` — ${finishDateText}`
  }
  return dateText
}

const query = graphql`
  query TimeBadgeQuery($locator: String!) {
    builds(locator: $locator) {
      build {
        id
      }
    }
  }
`

function usePipelineRunsArg(pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null) {
  const headId = usePipelineHeadId(pipelineHeadBuildTypeKey)
  const branch = useBranch()
  const branchLocator = getBranchLocator(branch, true)

  return [`count:1,buildType:(id:${headId})`, branchLocator].filter(Boolean).join(',')
}

export const useHasRuns = (pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null) => {
  const head = usePipelineHead(pipelineHeadBuildTypeKey)
  const headInternalId = head?.internalId

  const locator = usePipelineRunsArg(pipelineHeadBuildTypeKey)
  const [{builds}, refetch] = useRefetchableLazyLoadQuery<TimeBadgeQuery>(query, {
    locator,
  })

  useEffect(
    () =>
      headInternalId != null
        ? subscribeOnBuildTypeEvents(
            headInternalId,
            [
              BUILD_TYPE_ADDED_TO_QUEUE,
              BUILD_TYPE_REMOVED_FROM_QUEUE,
              BUILD_STARTED,
              BUILD_FINISHED,
              BUILD_INTERRUPTED,
            ],
            refetch,
          )
        : undefined,
    [headInternalId, refetch],
  )

  return !!builds?.build?.length
}

export const useDurationInfo = (runId?: BuildId) => {
  const dispatch = useAppDispatch()

  const data = useAppSelector(state => getBuild(state, runId))
  const {state: runState} = data ?? {}

  const isRunning = runState === 'running'
  const isQueued = runState === 'queued'

  const duration = useRunDuration(runId)
  const estimatedDuration = useRunRemainingTime(runId)
  const queueDuration = useTimeInQueue(runId)
  const date = useDisplayDate(runId)

  useEffect(() => {
    if (runId != null && isRunning) {
      return dispatch(subscribeOnBuild(runId))
    }
    return undefined
  }, [runId, isRunning, dispatch])

  return {
    duration,
    estimatedDuration,
    queueDuration,
    isRunning,
    isQueued,
    date,
  }
}
