import {Slider} from '@jetbrains/ring-ui-built/components/slider/slider'
import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import {capitalCase} from 'change-case'
import classNames from 'classnames'
import {Fragment, memo, useCallback, useEffect, useRef} from 'react'

import {useHasRuns} from '../../../../../../common/Badges/TimeBadge/TimeBadge.hooks'
import type {pipelineHeadBuildTypeFragment$key} from '../../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineId} from '../../../../hooks/pipeline'
import {StepTypes} from '../../../../types'
import {getDraftJobs} from '../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../slices/EditPipelinePage.slices'

import useJobParallelism from './JobParallelism.hooks'

import styles from './JobParallelism.module.css'

import HelpDetails from 'src/components/common/HelpDetails/HelpDetails'
import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type Props = {
  jobId: string
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
}

const MARKS = [{value: 2}, {value: 3}, {value: 4}, {value: 5}]
const SPEED_UP = 45
const STEP = 10
const supportedRunners: string[] = [StepTypes.MAVEN, StepTypes.GRADLE]

function JobParallelism({jobId, pipelineHeadBuildTypeKey}: Props) {
  const {parallelismCount, handleParallelismSelect} = useJobParallelism(jobId)

  const hasRuns = useHasRuns(pipelineHeadBuildTypeKey)

  const id = usePipelineId()
  const dispatch = useAppDispatch()

  const deletedSteps = useAppSelector(
    state => state.pipelines.pipelineDraft[id]?.deleted?.steps?.[jobId],
  )
  const applicable = useAppSelector(
    state =>
      !!getDraftJobs(state, id)?.[jobId]?.steps?.filter(
        ({type}, index) => !deletedSteps?.includes(index) && supportedRunners.includes(type),
      ).length,
  )

  const checked = !!parallelismCount && applicable
  const previousChecked = useRef(checked)

  const handleChange = useCallback(() => {
    if (checked) {
      handleParallelismSelect(null)
    } else {
      handleParallelismSelect(2)
    }
    previousChecked.current = !previousChecked.current
  }, [checked, handleParallelismSelect])

  const percent = SPEED_UP + MARKS.findIndex(({value}) => value === parallelismCount) * STEP
  const ref = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!applicable) {
      dispatch(
        pipelineDraft.actions.setParallelismCount({
          id,
          jobId,
          value: null,
        }),
      )
    }
  }, [dispatch, id, jobId, applicable])

  useEffect(() => {
    if (
      !previousChecked.current &&
      checked &&
      ref.current &&
      ref.current.getBoundingClientRect().bottom > window.innerHeight
    ) {
      ref.current?.scrollIntoView({behavior: 'smooth', block: 'center'})
    }
  }, [checked])

  return (
    <div data-test="parallel tests">
      <div className={styles.container}>
        <Toggle
          className={styles.toggle}
          checked={checked}
          disabled={!applicable}
          onChange={handleChange}
          help={
            applicable
              ? null
              : `Available only for ${supportedRunners.map(runner => capitalCase(runner)).join(', ')} runners`
          }
        >
          {'Parallel Tests'}
          <HelpDetails>
            {
              'Huge sets of tests can be split into smaller batches that run simultaneously on separate agents. As a result, your testing routines finish significantly faster (up to 75% with 5 batches, depending on a build).'
            }
            <br />
            <br />
            {'This technique is supported for the following runners:'}
            {supportedRunners.map(runner => (
              <Fragment key={runner}>
                <br />
                {`• ${capitalCase(runner)}`}
              </Fragment>
            ))}
          </HelpDetails>
        </Toggle>
      </div>
      {checked && (
        <div ref={ref}>
          <div className={classNames(styles.hint, styles.top)}>
            {'Specify the maximum number of batches for parallel tests execution'}
          </div>
          <Slider
            className={styles.slider}
            value={parallelismCount}
            min={1}
            max={5}
            showTag
            showTicks
            marks={MARKS}
            onChange={handleParallelismSelect}
          />
          <span className={styles.parallelismCount}>{`${parallelismCount} batches: `}</span>
          <span>{`up to ${percent}% faster`}</span>
          {!hasRuns && (
            <div className={styles.hint}>
              {
                'This feature needs at least one completed pipeline run to split the tests into batches. The first run will execute all tests in a single batch'
              }
            </div>
          )}
        </div>
      )}
    </div>
  )
}

export default memo(JobParallelism)
