import {memo} from 'react'

import useEventCallback from '../../../../../../../../../../hooks/useEventCallback'
import useBooleanState from '../../../../../../../hooks/useBooleanState'
import FilterRequirement from '../Filter/FilterRequirement'
import type {CustomRequirement} from '../SelfHostedRequirements.types'

import CustomRequirementDialog from './Dialog/CustomRequirementDialog'
import CustomRequirementTooltip from './Tooltip/CustomRequirementTooltip'

import ParametersIcon from 'src/svg/parameters.svg'

interface Props {
  requirement: CustomRequirement
  onChange: (prevRequirement: CustomRequirement, nextRequirement: CustomRequirement) => void
  onRemove: (requirement: CustomRequirement) => void
}

function CustomRequirementComponent(props: Props) {
  const {requirement, onChange, onRemove} = props
  const [isOpenDialog, openDialog, closeDialog] = useBooleanState(false)
  const handleRemoveClick = useEventCallback(() => {
    onRemove(requirement)
  })

  const onSave = useEventCallback((nextRequirement: CustomRequirement) => {
    onChange(requirement, nextRequirement)
  })

  return (
    <>
      <CustomRequirementTooltip requirement={requirement}>
        <FilterRequirement
          data-test={'custom-filter-requirement'}
          icon={ParametersIcon}
          active={isOpenDialog}
          onRemoveClick={handleRemoveClick}
          onClick={openDialog}
        >
          {requirement.name}
        </FilterRequirement>
      </CustomRequirementTooltip>
      {isOpenDialog && (
        <CustomRequirementDialog
          requirement={requirement}
          show
          onSave={onSave}
          onCloseAttempt={closeDialog}
        />
      )}
    </>
  )
}

export default memo(CustomRequirementComponent)
