import {memo} from 'react'

import type {RunnerSummarizePreviewProp} from '../../../../../components/RunnerSummarizePreview/RunnerSummarizePreview'
import RunnerSummarizePreview from '../../../../../components/RunnerSummarizePreview/RunnerSummarizePreview'
import {StepTypes, SuggestionType} from '../../../../../types'
import {SmartDetectors} from '../JobStep/SmartDetectors/SmartDetectors'

import JobStepRunnerSummarizeErrorPreview from './JobStepRunnerSummarizeErrorPreview/JobStepRunnerSummarizeErrorPreview'
import useJobStepRunnerSummarizeErrorPreview from './JobStepRunnerSummarizeErrorPreview/useJobStepRunnerSummarizeErrorPreview'
import useJobStepRunnerSummarizePreview from './useJobStepRunnerSummarizePreview'

import styles from './JobStepRunnerSummarizePreview.module.css'

type JobStepRunnerSummarizePreviewProps = {
  jobId: string
  isDragged?: boolean
  originalIndex: number
  cloneStepHandler: (index: number) => void
} & RunnerSummarizePreviewProp

const stepSuggestions: Record<string, SuggestionType[]> = {
  [StepTypes.MAVEN]: [SuggestionType.PARALLELISM],
  [StepTypes.GRADLE]: [SuggestionType.PARALLELISM],
}

function JobStepRunnerSummarizePreview({
  jobId,
  originalIndex,
  cloneStepHandler,
  ...props
}: JobStepRunnerSummarizePreviewProps) {
  const {
    isDeleted,
    selectedType,
    summarizeDetailsText,
    isSummarizeDetailsTextLoading,
    clickCloneRunnerHandler,
    deleteStepButtonClickHandler,
    clickRestoreButtonHandler,
    clickEditButtonHandler,
  } = useJobStepRunnerSummarizePreview(jobId, originalIndex, cloneStepHandler, props.runner)
  const {isShowError, ...errorProps} = useJobStepRunnerSummarizeErrorPreview()

  return (
    <div className={styles.container}>
      <RunnerSummarizePreview
        key={originalIndex}
        text={summarizeDetailsText}
        deleted={isDeleted}
        loading={isSummarizeDetailsTextLoading}
        onRestore={clickRestoreButtonHandler}
        onClone={clickCloneRunnerHandler}
        onEdit={clickEditButtonHandler}
        error={isShowError && <JobStepRunnerSummarizeErrorPreview {...errorProps} />}
        onDelete={deleteStepButtonClickHandler}
        bottomContent={
          selectedType &&
          stepSuggestions[selectedType]?.map((suggestion, i) => {
            const SmartDetector = SmartDetectors[suggestion]
            const key = `${originalIndex}-${suggestion}-${i}`

            return (
              SmartDetector && (
                <SmartDetector
                  key={key}
                  name={suggestion}
                  value={''}
                  stepIndex={originalIndex}
                  focused={false}
                />
              )
            )
          })
        }
        {...props}
      />
    </div>
  )
}

export default memo(JobStepRunnerSummarizePreview)
