import type {ButtonAttrs} from '@jetbrains/ring-ui-built/components/button/button'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import type {IconType} from '@jetbrains/ring-ui-built/components/icon/icon'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type * as React from 'react'
import {memo} from 'react'

import Tooltip from '../../../../../../../../../common/Tooltip/Tooltip'

import styles from './FilterRequirement.module.css'

type FilterRequirementProps = ButtonAttrs & {
  active: boolean
  className?: string
  icon: IconType | string
  iconClassName?: string
  iconWrapperClassName?: string
  onRemoveClick?: () => void
  children?: React.ReactNode
}
function FilterRequirement(props: FilterRequirementProps) {
  const {
    active,
    className,
    icon,
    iconClassName,
    iconWrapperClassName,
    loader,
    title,
    children,
    onRemoveClick,
    ...restProps
  } = props
  const classes = classNames(styles.filter, 'ring-button-withNormalIcon', className, {
    [styles.activeFilter]: active,
  })
  const iconWrapperClasses = classNames('ring-button-icon', iconWrapperClassName)
  return (
    <Button height={ControlsHeight.M} {...restProps} inline active={active} className={classes}>
      <span className={iconWrapperClasses}>
        <SvgIcon icon={icon} className={iconClassName} />
      </span>
      <span>{children}</span>
      {onRemoveClick && (
        <Tooltip
          popupProps={{
            directions: [Directions.TOP_CENTER, Directions.BOTTOM_CENTER],
          }}
          title={'Remove filter'}
          onClick={e => e.stopPropagation()}
        >
          <span data-test={'remove'} className={classNames(iconWrapperClasses, styles.close)}>
            <SvgIcon onClick={onRemoveClick} icon={'close'} className={iconClassName} />
          </span>
        </Tooltip>
      )}
    </Button>
  )
}

export default memo(FilterRequirement)
