import {useCallback, useMemo} from 'react'
import {useSearchParams} from 'react-router'

import {sideBarNavigatiobSearchParam} from '../../SettingsSidebarContent.const'

import useJobOutputParametersStore from './useJobOutputParametersStore'

function useJobOutputParameters() {
  const {
    jobOutputParameters,
    jobOutputParametersKeys,
    jobOutputParametersLength,
    formSpotParamId,
    formErrorSpotId,
    renamedJobOutputParameters,
    deletedJobOutputParameters,
    jobOutputParametersFormErrorMessage,
    changeNameHandler,
    changeValueHandler,
    restoreParametersHandler,
    deleteParametersHandler,
    confirmParametersHandler,
  } = useJobOutputParametersStore()
  const parametersControlValue = useMemo(
    () => ({
      parameters: jobOutputParameters,
      renamedParameters: renamedJobOutputParameters,
      formSpotParamId,
      formErrorSpotId,
      onNameChange: changeNameHandler,
      onValueChange: changeValueHandler,
      onRestore: restoreParametersHandler,
      onDelete: deleteParametersHandler,
      onConfirm: confirmParametersHandler,
    }),
    [
      changeNameHandler,
      changeValueHandler,
      confirmParametersHandler,
      deleteParametersHandler,
      formErrorSpotId,
      formSpotParamId,
      jobOutputParameters,
      renamedJobOutputParameters,
      restoreParametersHandler,
    ],
  )
  const [searchParams, setSearchParams] = useSearchParams()
  const collapsedNote = useMemo(
    () =>
      jobOutputParametersKeys
        .map(key => `${renamedJobOutputParameters?.[key] ?? key}=${jobOutputParameters[key]}`)
        .join(', '),
    [jobOutputParameters, jobOutputParametersKeys, renamedJobOutputParameters],
  )
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const clickEditJobParametersHandler = useCallback(
    () =>
      setSearchParams({
        ...searchParamsObject,
        [sideBarNavigatiobSearchParam.outputParameters]: 'true',
      }),
    [searchParamsObject, setSearchParams],
  )

  return {
    jobOutputParameters,
    jobOutputParametersKeys,
    jobOutputParametersLength,
    deletedJobOutputParameters,
    collapsedNote,
    jobOutputParametersFormErrorMessage,
    parametersControlValue,
    clickEditJobParametersHandler,
  }
}

export default useJobOutputParameters
