import ChipStatus from '../../../../components/ChipStatus/ChipStatus'

type JobAgentRequirementsSelectLabelProps = {
  compatible: boolean
}

function JobAgentRequirementsSelectLabel({compatible}: JobAgentRequirementsSelectLabelProps) {
  const chipStatus = compatible ? 'standard' : 'warning'
  const chipStatusText = compatible ? 'Compatible' : 'Incompatible'

  return <ChipStatus status={chipStatus}>{chipStatusText}</ChipStatus>
}

export default JobAgentRequirementsSelectLabel
