import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../hooks/pipeline'
import {getDraftJobs} from '../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../slices/EditPipelinePage.slices'

function useJobParallelism(jobId: string) {
  const pipelineId = usePipelineId()
  const parallelismCount = useAppSelector(
    state => getDraftJobs(state, pipelineId)?.[jobId]?.parallelism,
  )
  const dispatch = useAppDispatch()
  const handleParallelismSelect = (value: number | number[] | null) => {
    dispatch(
      pipelineDraft.actions.setParallelismCount({
        id: pipelineId,
        jobId,
        value: value === 1 ? 2 : Number(value),
      }),
    )
  }

  return {
    parallelismCount,
    handleParallelismSelect,
  }
}

export default useJobParallelism
