import {useCallback, useEffect, useState} from 'react'
import {useSearchParams} from 'react-router'

import {useAppStore} from '../../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {pipelinesApi} from '../../../../../services/pipelinesApi'
import {getResolvedSettings} from '../../../../EditPipelinePage.selectors'

function useJobStepRunnerSummarize() {
  const pipelineId = usePipelineId()
  const [editStepId, setEditStepId] = useState<string | null>(null)
  const [searchParams] = useSearchParams()
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const [fetchBuildStepDescription, {buildStepsDescription, isBuildStepsDescriptionLoading}] =
    pipelinesApi.endpoints.getBuildStepDescription.useLazyQuery({
      selectFromResult: ({isFetching, isLoading, data}) => ({
        buildStepsDescription: data,
        isBuildStepsDescriptionLoading: isFetching || isLoading,
      }),
    })
  const {getState} = useAppStore()
  const getPipelineDraftState = useCallback(
    () =>
      getResolvedSettings(getState(), pipelineId, {
        excludeDeleted: true,
        excludeReordered: true,
      }),
    [getState, pipelineId],
  )
  const loadBuildStepDescription = useCallback(async () => {
    const pipelineDraftState = getPipelineDraftState()

    if (pipelineDraftState != null) {
      await fetchBuildStepDescription({
        id: pipelineId,
        body: pipelineDraftState,
      })
    }
  }, [fetchBuildStepDescription, getPipelineDraftState, pipelineId])

  useEffect(() => {
    if (searchParamsObject?.step) {
      setEditStepId(searchParamsObject.step)
    }

    if (!searchParamsObject?.step && editStepId) {
      loadBuildStepDescription().then(() => setEditStepId(null))
    }
  }, [editStepId, loadBuildStepDescription, searchParamsObject.step])

  useEffect(() => {
    if (!searchParamsObject?.step) {
      loadBuildStepDescription()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return {
    loadBuildStepDescription,
    editStepId,
    buildStepsDescription,
    isBuildStepsDescriptionLoading,
  }
}

export default useJobStepRunnerSummarize
