import type {PopupMenuAttrs} from '@jetbrains/ring-ui-built/components/popup-menu/popup-menu'
import * as React from 'react'

const PopupMenuLazy = React.lazy(
  () =>
    import(
      /* webpackChunkName: "PopupMenu" */
      './PopupMenu'
    ),
)

function PopupMenu(props: PopupMenuAttrs) {
  return props.hidden === true && process.env.NODE_ENV !== 'test' ? null : (
    <React.Suspense fallback="">
      <PopupMenuLazy {...props} />
    </React.Suspense>
  )
}

export default PopupMenu
