import CheckmarkIcon from '@jetbrains/icons/checkmark.svg'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/list'
import List from '@jetbrains/ring-ui-built/components/list/list'
import {useMemo, useState} from 'react'

import {Size} from '../../../../../../../components/Input'
import Input from '../../../../../../../components/Input/Input'
import styles from '../SelfHostedRequirements.module.css'
import {cpuCountList, type CpuCountRequirement} from '../SelfHostedRequirements.types'

interface Props {
  requirement?: CpuCountRequirement
}

export const useCPURequirement = (props?: Props) => {
  const {requirement} = props ?? {}
  const [nextRequirement, setNextRequirement] = useState<CpuCountRequirement | null>(null)

  const currentRequirement = nextRequirement ?? requirement

  const data: ReadonlyArray<ListDataItem> = useMemo(
    () => [
      ...cpuCountList.map(cpu => ({
        label: cpu.toString(),
        key: cpu.toString(),
        rightGlyph: currentRequirement?.cpu === cpu ? CheckmarkIcon : null,
        onClick: () => {
          setNextRequirement({
            cpu,
          })
        },
      })),
      {
        rgItemType: List.ListProps.Type.CUSTOM,
        template: (
          <Input
            type="number"
            placeholder="Number"
            inputClassName={styles.numberInput}
            spellCheck={false}
            size={Size.FULL}
            value={currentRequirement?.cpu?.toString() ?? ''}
            min={1}
            onChange={e => {
              setNextRequirement({
                cpu: Number(e.currentTarget.value),
              })
            }}
            autoComplete="off"
          />
        ),
      },
    ],
    [currentRequirement?.cpu],
  )

  const reset = () => setNextRequirement(null)

  return {
    data,
    currentRequirement,
    reset,
  }
}
