import {memo} from 'react'

import SettingsBlock from '../../../../components/SettingsBlock/SettingsBlock'
import type {pipelineHeadBuildTypeFragment$key} from '../../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {dependencyCacheEnabled} from '../../../../utils/featureToggles'
import JobAllowReuse from '../JobAllowReuse/JobAllowReuse'
import JobEnableDependencyCache from '../JobEnableDependencyCache/JobEnableDependencyCache'
import JobParallelism from '../JobParallelism/JobParallelism'

import JobOptimizationsNote from './JobOptimizationsNote/JobOptimizationsNote'

import styles from './JobOptimizations.module.css'

type Props = {
  jobId: string
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
}

function JobOptimizations({jobId, pipelineHeadBuildTypeKey}: Props) {
  return (
    <SettingsBlock
      id={'optimizations'}
      title={'Optimizations'}
      collapsible
      collapsibleClassName={styles.settings}
      collapsedNote={<JobOptimizationsNote jobId={jobId} />}
    >
      <JobParallelism jobId={jobId} pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey} />
      {dependencyCacheEnabled && <JobEnableDependencyCache jobId={jobId} />}
      <JobAllowReuse jobId={jobId} />
    </SettingsBlock>
  )
}

export default memo(JobOptimizations)
