import fuzzyHighlight from '@jetbrains/ring-ui-built/components/global/fuzzy-highlight'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'

import {
  getParameterSuggestionItem,
  getValueSuggestionItem,
} from '../../../../../../../../components/HighlighterTextFieldItem/HighlighterTextFieldItem.utils'
import type {PipelineParametersResolve} from '../../../../../../../../services/pipelinesApi.types'

export function getParameterSuggestionList(
  parametersResolve: PipelineParametersResolve[],
  parameter = '',
) {
  return parametersResolve.map(param => {
    const {name, type, values} = param
    const fuzzySearch = parameter != null ? fuzzyHighlight(parameter, name) : null
    const matches = fuzzySearch ? fuzzySearch.matches : []

    return getParameterSuggestionItem(name, type, values, matches)
  })
}

export function getValueSuggestionList(values: string[], value = '') {
  return values.map(val => {
    const fuzzySearch = value != null ? fuzzyHighlight(value, val) : null
    const matches = fuzzySearch ? fuzzySearch.matches : []

    return getValueSuggestionItem(val, matches)
  })
}

export const onChangeSelect = (selected: SelectItem | null, onAction: (value: string) => void) => {
  const key = selected?.key

  if (selected == null) {
    onAction('')
  }
  if (typeof key === 'string') {
    onAction(key)
  }
  if (typeof key === 'number' && typeof selected?.label === 'string') {
    onAction(selected.label)
  }
}
