import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import PopupMenu from '@jetbrains/ring-ui-built/components/popup-menu/popup-menu'
import type {ReactElement} from 'react'
import {useSearchParams} from 'react-router'

import {sideBarNavigatiobSearchParam} from '../../../SettingsSidebarContent.const'

import styles from './JobOutputsSettingsBlockCustomActions.module.css'

type JobOutputsSettingsBlockCustomActionsProps = {
  anchor: ReactElement
}

function JobOutputsSettingsBlockCustomActions({anchor}: JobOutputsSettingsBlockCustomActionsProps) {
  const [searchParams, setSearchParams] = useSearchParams()
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const clickEditJobOutputParametersHandler = () =>
    setSearchParams({
      ...searchParamsObject,
      [sideBarNavigatiobSearchParam.outputParameters]: 'true',
    })
  const clickEditJobSharedFilesHandler = () =>
    setSearchParams({
      ...searchParamsObject,
      [sideBarNavigatiobSearchParam.sharedFiles]: 'true',
    })

  return (
    <Dropdown className={styles.addIntegration} anchor={anchor}>
      <PopupMenu
        className={styles.popupMenu}
        data={[
          {
            label: 'Parameters',
            onClick: clickEditJobOutputParametersHandler,
          },
          {
            label: 'Files',
            onClick: clickEditJobSharedFilesHandler,
          },
        ]}
        closeOnSelect
      />
    </Dropdown>
  )
}

export default JobOutputsSettingsBlockCustomActions
