import {useAppSelector} from '../../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {getJobName} from '../../../../EditPipelinePage.selectors'

type Props = {
  dependencies: string[]
}

function JobDependenciesNote({dependencies}: Props) {
  const id = usePipelineId()
  const note = useAppSelector(state =>
    dependencies.map(depId => getJobName(state, id, depId)).join(', '),
  )
  return <>{note}</>
}

export default JobDependenciesNote
